let db;try{db=JSON.parse(localStorage.getItem(KEY));if(db?.version!==1)db=null;}catch{}db ||= seed();db.accounts ||= seedAccounts(db.employees);db.sessionsByEmployee ||= {'EMP-001':db.session};db.settings ||= {company:'Bevy Commerce',portal:'Internal HR Portal',timezone:'Asia/Dhaka',targetHours:8};db.announcements ||= [{id:'ANN-WELCOME',title:'Welcome to your Bevy workspace',body:'Share progress in Daily Updates, manage your leave, and check completed insurance payments—all in one place.',at:new Date().toISOString(),audience:'Everyone'}];
