const menu=[['Dashboard','◫'],['Daily updates','☷'],['My profile','♧'],['Leave','◷'],['Insurance','♡'],['Expenses','▧'],['Employees','♧'],['Assets','▣'],['Archived employees','▤'],['Performance','◇','Future'],['Control centre','⚒'],['Access management','⛨'],['Portal settings','⚙'],['Activity log','≡'],['Build guide','↗']];
const person=id=>db.employees.find(e=>e.id===id),active=()=>db.employees.filter(e=>e.status==='Active'),account=()=>db.accounts.find(a=>a.employeeId===employeeId),superAdmin=()=>account()?.role==='Super Admin'&&account()?.status==='Active',can=key=>permitted(account(),key),hr=()=>account()?.status==='Active'&&['Super Admin','HR Admin'].includes(account()?.role),lead=()=>hr();
