function badge(s){return `<span class="badge ${/Pending|Overdue|Repair|Unconfirmed|Missing|review/.test(s)?'warn':/Rejected|Declined|Archived/.test(s)?'red':/Contract|Future/.test(s)?'blue':''}">${esc(s)}</span>`;}
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const options=(arr,value,all='')=>(all?`<option value="">${esc(all)}</option>`:'')+arr.map(x=>`<option ${x===value?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');
