function renderShell(){role=account()?.role||'Employee';const allowed=menu.filter(([v])=>mayView(v));const groups=[['YOUR WORK',['Dashboard','Daily updates','My profile','Leave','Insurance','Expenses']],['PEOPLE OPERATIONS',['Employees','Assets','Archived employees','Performance']],['ADMINISTRATION',['Control centre','Access management','Portal settings','Activity log','Build guide']]];$('#sidebar').innerHTML=`<div class="brand"><img src="bevy-logo.svg" alt="Bevy Commerce"><small>INTERNAL HR PORTAL</small></div>${groups.map(([label,items])=>{const a=allowed.filter(([v])=>items.includes(v));return a.length?`<div class="nav-label">${label}</div><nav>${a.map(([v,i,f])=>`<button data-nav="${v}" class="${v===view?'active':''}"><span class="icon" aria-hidden="true">${i}</span>${v}${f?'<em>FUTURE</em>':''}</button>`).join('')}</nav>`:'';}).join('')}<div class="sidebar-bottom"><div class="sidebar-person"><span class="avatar">${initials(person(employeeId)?.name||'Bevy')}</span><div><b>${esc(person(employeeId)?.name||'Bevy colleague')}</b><small>${esc(role)}</small></div></div><p>Bevy Commerce · People & Culture</p></div>`;
$('#topbar').innerHTML=`<div class="actions"><button class="mobile-toggle" data-action="menu" aria-label="Toggle navigation">☰</button><div class="breadcrumb">Bevy workspace <span>/</span><b>${esc(view)}</b></div></div><div class="header-right">${btn('Login screen','login-preview')}<button class="search-launch" data-action="quick-search"><span>⌕</span> Find a page or person <kbd>⌘ K</kbd></button><button class="portal-clock" data-action="daily" title="Working time starts when you enter the portal"><span class="live-indicator"></span><span id="portal-clock">${hms(db.session?netSeconds(db.session):0)}</span><small>${db.session?.ended?'Day closed':db.session?.pausedAt?'On break':'Working'}</small></button><button class="inbox-button" data-action="inbox" aria-label="Open attention centre"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><i>${attentionItems().length}</i></button><label class="preview-picker"><span>Demo view</span><select id="role" aria-label="Preview role">${options(ROLES,role)}</select></label></div>`;}
function render(){initializeWorkspace();if(!loggedIn){renderLogin();return;}document.body.classList.remove('login-mode');ensurePortalSession();if(!mayView(view))view='Dashboard';renderShell();let html='';if(profileId&&(view==='Employees'||view==='My profile'))html=profile();else switch(view){case'Dashboard':html=dashboard();break;case'Employees':html=employees();break;case'My profile':profileId=employeeId;html=profile();break;case'Assets':html=assets();break;case'Leave':html=leave();break;case'Insurance':html=insurance();break;case'Expenses':html=expenseModule();break;case'Archived employees':html=archives();break;case'Daily updates':html=daily();break;case'Performance':html=performance();break;case'Build guide':html=guide();break;case'Control centre':html=controlCentre();break;case'Access management':html=accessManagement();break;case'Portal settings':html=portalSettings();break;case'Activity log':html=activity();break;}$('#main').innerHTML=html;}
function renderLogin(){document.body.classList.add('login-mode');$('#sidebar').innerHTML='';$('#topbar').innerHTML='';$('#main').innerHTML=`<section class="login-card card"><img src="bevy-logo.svg" width="180" alt="Bevy Commerce"><div class="eyebrow">YOUR PEOPLE. YOUR WORKSPACE.</div><h1>Welcome to Bevy.</h1><p>Sign in to your daily workspace. Your working timer starts automatically after successful portal login.</p><div class="notice">Interactive login preview · Fictional accounts only. Hosted company sign-in remains the access gate.</div>${btn('Enter demo workspace →','portal-login','primary')}<p class="small muted">8 net hours · Flexible start · Breaks excluded<br>Returning today resumes the same timer. A closed day stays closed. An unfinished prior day must be resolved before a new day starts.</p></section>`;}
function dashboard(){const done=db.claims.filter(completed),pending=db.leaves.filter(l=>l.status==='Pending');return heading('Your workspace. Your day.','Bevy Commerce · '+date(today()),btn('Open daily updates →','daily','primary'))+dashboardAnnouncement()+workPanel(true)+`<div class="grid dashboard-stats">${hr()?stat('Active employees',active().length,'Across 8 departments','♧')+stat('Available devices',db.assets.filter(a=>a.status==='Available'||a.status==='Returned').length,'Ready for assignment','▣'):stat('My assigned devices',db.assets.filter(a=>a.status==='Assigned'&&a.employeeId===employeeId).length,'Equipment in my care','▣')+stat('My pending leave',db.leaves.filter(l=>l.employeeId===employeeId&&l.status==='Pending').length,'Awaiting review','◷')}${stat('Completed claims',done.length,'Confirmed bank payments','♡')}</div><div class="grid two"><section class="card"><div class="section-head"><h2>Today’s checkpoints</h2><span class="small muted">${db.session?.date===today()?'Today':'Open workday'}</span></div><div class="row"><span class="avatar">01</span><div class="grow"><strong>Mid-Day update</strong><p>${db.session?.mid?'Progress shared with your team.':db.session?.missReason?'Reason recorded for HR review.':'Around 4 net working hours.'}</p></div>${badge(db.session?.mid?'Submitted':db.session?.missReason?'Pending review':db.session?.ended?'Missing':db.session&&netSeconds(db.session)>=14400?'Due':'Upcoming')}</div><div class="row"><span class="avatar">02</span><div class="grow"><strong>End-of-day handover</strong><p>Submit before finishing; allow 30–45 minutes for feedback.</p></div>${badge(db.session?.eod?'Submitted':'Upcoming')}</div><div class="actions" style="margin-top:16px">${btn('Share an update →','daily','primary')}</div></section><section class="card"><div class="section-head"><h2>${hr()?'Administrative attention':'Quick access'}</h2></div>${can('leave')?`<div class="row"><div class="grow"><strong>${pending.length} leave requests</strong><p>Awaiting review</p></div>${btn('Review','leave')}</div>${can('archives')?`<div class="row"><div class="grow"><strong>${db.employees.filter(e=>e.status==='Archived'&&archiveEligible(e.offboarded,today())).length} archive decisions</strong><p>Records retained for at least 30 days</p></div>${btn('Open','archives')}</div>`:''}`:`<div class="row"><div class="grow"><strong>My profile & assets</strong><p>Your employment details in one place</p></div>${btn('Open','my-profile')}</div>`}<div class="row"><div class="grow"><strong>Insurance payments</strong><p>Completed claims and stage timelines</p></div>${btn('View','insurance')}</div></section></div>`;}
