function employees(){if(!can('people'))return denied();const a=filteredEmployees(),pages=Math.max(1,Math.ceil(a.length/10));empPage=Math.min(empPage,pages);return heading('Your people, at a glance.','Find a colleague by name or email. Archived results require archive access.',`${btn('Export CSV','export-employees')}${hr()?btn('+ Add employee','add-employee','primary'):''}`)+`<div class="filters"><input type="search" id="employee-search" aria-label="Search employees" placeholder="Search by name or email…" value="${esc(empQuery)}">${[['department','Department',departments],['position','Position',[...new Set(active().map(e=>e.position))]],['type','Employee type',['Full-time','Contract']],['manager','Manager',[...new Set(active().map(e=>e.manager))]],['location','Location',['Bangladesh','Pakistan','Canada']],['status','Employee status',can('archives')?['Active','Archived','All records']:['Active']]].map(([key,name,a])=>`<label>${name}<select data-filter="${key}">${options(a,filters[key], 'All '+name.toLowerCase()+'s')}</select></label>`).join('')}${btn('Clear','clear-filters')}</div><div class="table-wrap mobile-cards"><table><thead><tr>${['Employee','Department','Position','Location','Joined','Status',''].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${a.slice((empPage-1)*10,empPage*10).map(e=>`<tr><td data-label="Employee"><div class="person"><span class="avatar">${initials(e.name)}</span><div><button class="text-btn" data-profile="${e.id}">${esc(e.name)}</button><small>${esc(e.email)}</small></div></div></td><td data-label="Department">${esc(e.department)}</td><td data-label="Position">${esc(e.position)}<small>${esc(e.type)}</small></td><td data-label="Location">${esc(e.location)}</td><td data-label="Joined">${date(e.joined)}</td><td data-label="Status">${badge(e.status)}</td><td>${btn('View →','profile','',`data-id="${e.id}"`)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No matching employees. Try clearing the filters.</td></tr>'}</tbody></table></div><div class="pagination"><span>${a.length?((empPage-1)*10+1):0}–${Math.min(empPage*10,a.length)} of ${a.length} employees</span><div class="actions">${btn('← Previous','emp-prev','',empPage===1?'disabled':'')}<span>Page ${empPage} of ${pages}</span>${btn('Next →','emp-next','',empPage===pages?'disabled':'')}</div></div>`;}
function fields(e,items){return `<div class="form-grid">${items.map(([key,label])=>`<div class="field"><small>${label}</small><span>${esc(['joined','dob'].includes(key)?date(e[key]):e[key]??'—')}</span></div>`).join('')}</div>`;}
function profile(){const e=person(profileId);if(!e||(!can('people')&&e.id!==employeeId))return denied();const tabs=['Overview',...(can('confidential')?['Personal & confidential']:[]),'Assigned assets'];if(!tabs.includes(profileTab))profileTab='Overview';const months=monthsSince(e.joined,today()),coverage=profileCoverage(e);return heading('Employee profile','One record for employment, experience, and assigned devices.',`${btn('← Back','back-employees')}${can('archives')&&e.status==='Active'?btn('Offboard','offboard','danger',`data-id="${e.id}"`):''}${can('people')?btn('Edit profile','edit-profile','primary',`data-id="${e.id}"`):''}`)+`<div class="profile-head"><span class="avatar">${initials(e.name)}</span><div><h2>${esc(e.name)}</h2><p class="muted small">${esc(e.position)} · ${esc(e.department)}</p><div class="pill-row">${badge(e.status)}${badge(e.type)}<span class="muted small">${e.id}</span></div></div>${can('confidential')?`<div class="profile-completion"><strong>${coverage.complete}/${coverage.total}</strong><span>Profile fields completed</span><small>SWIFT/BIC optional · scope §3–4</small></div>`:''}</div><div class="tabs">${tabs.map(t=>`<button data-profile-tab="${t}" class="${profileTab===t?'active':''}">${t}</button>`).join('')}</div><div class="profile-layout"><section class="card profile-sidebar"><h3>At Bevy</h3><div class="field"><small>Company email</small>${esc(e.email)}</div><div class="field"><small>Reporting manager</small>${esc(e.manager)}</div><div class="field"><small>Work location</small>${esc(e.location)}</div><div class="field"><small>Bevy experience</small>${experience(months)}</div>${can('archives')&&e.status==='Active'?`<div style="margin-top:20px">${btn('Offboard employee','offboard','danger',`data-id="${e.id}"`)}</div>`:''}</section><section class="card">${profileTab==='Overview'?`<div class="profile-section-label"><span>01</span><h3>Employment information</h3></div>${fields(e,jobFields)}<h3 style="margin-top:28px">Education & experience</h3>${fields(e,[['education','University-level education qualification']])}<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px"><div class="stage"><small>Previous experience</small><strong style="font-size:20px">${experience(+e.previousMonths)}</strong></div><div class="stage"><small>At Bevy · automatic</small><strong style="font-size:20px">${experience(months)}</strong></div><div class="stage"><small>Total experience</small><strong style="font-size:20px">${experience(months+(+e.previousMonths))}</strong></div></div><p class="small muted" style="margin-top:18px">Calculated from the joining date to today, using completed months.</p>${!can('confidential')?'<div class="notice">Sensitive personal and banking information is restricted to authorized HR/Admin.</div>':''}`:profileTab==='Personal & confidential'?`<div class="notice">Confidential details · Authorized administrators only. All identifiers shown here are fictional.</div><div class="profile-section-label"><span>01</span><h3>Personal information</h3></div>${fields(e,personalFields)}<h3 style="margin-top:28px">Confidential bank information</h3>${fields(e,bankFields)}`:`<h3>Assigned assets</h3>${db.assets.filter(a=>a.employeeId===e.id&&a.status==='Assigned').map(a=>`<div class="row"><span class="avatar">▣</span><div class="grow"><strong>${esc(a.name)}</strong><p>${esc(a.serial)} · Assigned ${date(a.assigned)}</p></div>${badge(a.status)}</div>`).join('')||'<div class="empty">No devices currently assigned.</div>'}${can('assets')&&e.status==='Active'?btn('+ Assign a device','assign-asset','primary',`data-employee="${e.id}"`):''}`}</section></div>`;}
function assets(){if(!can('assets'))return denied();const q=filters.assetQ||'',status=filters.assetStatus||'';const a=db.assets.filter(a=>`${a.name} ${a.serial} ${person(a.employeeId)?.name||''}`.toLowerCase().includes(q.toLowerCase())&&(!status||a.status===status));return heading('Every device. Accounted for.','Assign exact devices, track returns, and keep your inventory clear.',hr()?`${btn('+ Add asset','add-asset')}${btn('Assign device','assign-asset','primary')}`:'')+`<div class="grid stats">${['Available','Assigned','Returned','Repair'].map(s=>stat(s,db.assets.filter(a=>a.status===s).length,'Devices in inventory','▣')).join('')}</div><div class="filters"><input type="search" id="asset-search" aria-label="Search devices" placeholder="Search model, serial or employee…" value="${esc(q)}"><label>Status<select id="asset-status">${options(['Available','Assigned','Returned','Repair'],status,'All statuses')}</select></label></div><div class="table-wrap mobile-cards"><table><thead><tr>${['Device / model','Serial number','Assigned to','Assigned','Return date','Status','Action'].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${a.map(a=>`<tr><td data-label="Device"><b>${esc(a.name)}</b><small>${esc(a.type)} · ${esc(a.model)}</small></td><td data-label="Serial">${esc(a.serial)}</td><td data-label="Employee">${esc(person(a.employeeId)?.name||'—')}</td><td data-label="Assigned">${date(a.assigned)}</td><td data-label="Returned">${date(a.returned)}</td><td data-label="Status">${badge(a.status)}</td><td>${can('assets')?btn('Edit details','edit-asset','',`data-id="${a.id}"`)+btn('History','asset-history','',`data-id="${a.id}"`)+(a.status==='Assigned'?btn('Record return','return-asset','',`data-id="${a.id}"`):['Available','Returned'].includes(a.status)?btn('Assign','assign-asset','',`data-id="${a.id}"`):btn('Mark available','repair-done','',`data-id="${a.id}"`)):'—'}</td></tr>`).join('')||'<tr><td class="empty" colspan="7">No matching devices.</td></tr>'}</tbody></table></div><p class="small muted">${a.length} results · Return date is optional until the device is actually returned. No employee request workflow.</p>`;}
function archives(){if(!can('archives'))return denied();const a=db.employees.filter(e=>e.status==='Archived');return heading('Keep history. Stay in control.','Offboarded employees are removed from the active directory.')+`<div class="notice">Nothing is deleted automatically. After 30 calendar days, HR can keep a record archived or explicitly delete it.</div><div class="table-wrap mobile-cards"><table><thead><tr>${['Employee','Department','Offboarded','Retention','Actions'].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${a.map(e=>`<tr><td data-label="Employee"><b>${esc(e.name)}</b><small>${esc(e.email)}</small></td><td data-label="Department">${esc(e.department)}</td><td data-label="Offboarded">${date(e.offboarded)}</td><td data-label="Retention">${archiveEligible(e.offboarded,today())?badge('Decision available'):badge('Within 30 days')}<small>${esc(e.archiveNote)}${e.retentionDecisions?.length?' · '+e.retentionDecisions.length+' retention decision(s)':''}</small></td><td><div class="actions">${btn('View','archived-profile','',`data-id="${e.id}"`)}${btn('Restore','restore','',`data-id="${e.id}"`)}${btn('Edit archive','edit-archive','',`data-id="${e.id}"`)}${btn('Keep archived','keep-archived','',`data-id="${e.id}"`)}${btn('Delete','delete-employee','danger',`data-id="${e.id}" ${!archiveEligible(e.offboarded,today())?'disabled':''}`)}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No archived employees.</td></tr>'}</tbody></table></div>`;}
function leave(){const a=db.leaves.filter(l=>can('leave')||l.employeeId===employeeId);return heading('Time away, made simple.','January 1–December 31 · Vacation 11 · Floater Day 3 · Sick Leave unlimited · No accrual or carry-over.',btn('+ Request leave','request-leave','primary'))+`<div class="notice">Balances reserve pending requests. Friday/Saturday excluded. Sick Leave: medical document optional for 1 day, required above ${db.settings.medicalThreshold} working days (provisional threshold; confirm 2 or 3). ${can('leave')&&can('configuration')?btn('Medical document policy','medical-policy'):''}</div><div class="grid stats">${LEAVE_TYPES.map(t=>{const b=leaveBalance(db.leaves,employeeId,t,today().slice(0,4));return stat(t,b.allowance===Infinity?'Unlimited':b.available+' / '+b.allowance,'My '+today().slice(0,4)+' balance · '+b.pending+' pending','◷');}).join('')}${stat('Pending requests',a.filter(l=>l.status==='Pending').length,'Awaiting review','◷')}${stat('Approved requests',a.filter(l=>l.status==='Approved').length,'Available to daily updates','✓')}</div><div class="table-wrap mobile-cards"><table><thead><tr>${['Employee','Leave type','Dates','Reason','Status',''].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${a.map(l=>`<tr><td data-label="Employee">${esc(person(l.employeeId)?.name||'Archived employee')}</td><td data-label="Type">${esc(l.type)}</td><td data-label="Dates">${date(l.from)} → ${date(l.to)}</td><td data-label="Reason">${esc(l.reason)}${l.type==='Sick Leave'?`<br><small class="muted">Medical document: ${l.medicalDoc?esc(l.medicalDoc)+' (filename only)':'Not supplied'}</small>`:''}</td><td data-label="Status">${badge(l.status)}</td><td>${can('leave')?btn('Edit request','edit-leave','',`data-id="${l.id}"`):''}${can('leave')&&l.status==='Pending'?`<div class="actions">${btn('Approve','approve-leave','',`data-id="${l.id}"`)}${btn('Decline','decline-leave','danger',`data-id="${l.id}"`)}</div>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No leave requests yet.</td></tr>'}</tbody></table></div>`;}
function claimSelection(){const range=rangeFor(claimPeriod,today(),claimMonth,claimFrom,claimTo),q=claimQuery.toLowerCase();return {range,done:db.claims.filter(c=>completed(c)&&inRange(c.bank,range)&&`${c.id} ${c.tracking} ${c.member}`.toLowerCase().includes(q)),rejected:db.claims.filter(c=>c.status==='Rejected'&&inRange(c.start,range)).length,overdue:db.claims.filter(c=>c.status==='Overdue'&&inRange(c.start,range)).length};}
function insurance(){const {done,rejected,overdue}=claimSelection(),size=claimSize===0?Math.max(1,done.length):claimSize,pages=Math.max(1,Math.ceil(done.length/size));claimPage=Math.min(claimPage,pages);const avgStages=[0,1,2].map(i=>average(done.map(c=>stages(c)[i])).toFixed(1));return heading('Insurance, with clarity.','A transparent view of settled claims and how quickly payments move.',`${can('insurance')?btn('HR tracker preview','hr-claims'):''}${btn('↻ Refresh','refresh-claims','primary')}`)+`<div class="notice ${claimFailure?'red':''}" id="refresh-notice">${claimFailure?'Refresh failed — previously loaded demo data remains visible.':'● Demo dataset loaded · Auto-refresh every 60 seconds while open.'} Last successful update: ${time(lastRefresh)}.</div><div class="filters"><label>Reporting period<select id="claim-period">${[['all','All time'],['30','Last 30 days'],['month','This month'],['choose','Choose a month'],['year','This year'],['custom','Custom dates']].map(([v,t])=>`<option value="${v}" ${claimPeriod===v?'selected':''}>${t}</option>`).join('')}</select></label>${claimPeriod==='choose'?`<label>Month<input type="month" id="claim-month" value="${claimMonth}"></label>`:claimPeriod==='custom'?`<label>From<input type="date" id="claim-from" value="${claimFrom}"></label><label>To<input type="date" id="claim-to" value="${claimTo}"></label>`:''}<input type="search" id="claim-search" aria-label="Search claims" value="${esc(claimQuery)}" placeholder="Claim, tracking reference or member ID…">${btn('Clear','clear-claims')}</div>${claimPeriod==='custom'&&claimFrom>claimTo?'<div class="notice red">Start date must be before the end date.</div>':''}<div class="grid stats">${stat('Completed claims',done.length,'Filtered by bank receipt date','✓')}${stat('Insurer rejections',rejected,'Filtered by recorded start date','↗')}${stat('Average payment time',average(done.map(c=>workingDays(c.start,c.bank))).toFixed(1)+' <span style="font-size:14px">days</span>','Recorded start → confirmed bank receipt','◷')}${stat('Overdue classification',overdue,'Separate from insurer rejections','!')}</div><section class="card" style="margin-bottom:22px"><div class="section-head"><h2>Where the time goes</h2><span class="small muted">Average working days</span></div><div class="timeline">${['Recorded start → Insurer received','Insurer received → Settlement','Settlement → Bank payment'].map((s,i)=>`<div class="stage"><small>${s}</small><strong>${avgStages[i]} <span style="font-size:12px;font-weight:400">days</span></strong></div>`).join('')}</div><p class="small muted" style="margin:14px 0 0">Friday & Saturday excluded · Holidays not excluded · Same-day stages = 0 · Averages calculated before rounding.</p></section><div class="section-head"><h2>Confirmed payments</h2><label>Show<select id="claim-size">${[[10,'10 claims'],[25,'25 claims'],[0,'All claims']].map(([n,t])=>`<option value="${n}" ${claimSize===n?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="table-wrap mobile-cards"><table><thead><tr>${['Reference','Member / type','Paid','Insurer received','Settled','Bank received','Working days',''].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${done.slice((claimPage-1)*size,claimPage*size).map(c=>`<tr><td data-label="Reference"><b>${c.id}</b><small>${c.tracking}</small></td><td data-label="Member / type">${esc(maskMemberId(c.member))}<small>${c.type}</small></td><td data-label="Paid">${money(c.paid)}</td><td data-label="Insurer received">${date(c.received)}</td><td data-label="Settled">${date(c.settled)}</td><td data-label="Bank received">${date(c.bank)}<small>Confirmed ✓</small></td><td data-label="Working days"><b>${workingDays(c.start,c.bank)}</b><small>${stages(c).join(' / ')} by stage</small></td><td>${btn('Timeline','claim-detail','',`data-id="${c.id}"`)}${can('insurance')?btn('Edit sample','edit-claim','',`data-id="${c.id}"`):''}</td></tr>`).join('')||'<tr><td class="empty" colspan="8">No confirmed claims for these filters.</td></tr>'}</tbody></table></div><div class="pagination"><span>${done.length?(claimPage-1)*size+1:0}–${Math.min(claimPage*size,done.length)} of ${done.length} confirmed claims</span><div class="actions">${btn('← Previous','claim-prev','',claimPage===1?'disabled':'')}<span>${claimPage} / ${pages}</span>${btn('Next →','claim-next','',claimPage===pages?'disabled':'')}</div></div><p class="small muted">Start basis: actual submission where recorded; otherwise HR approval. Each timeline labels its basis. Names, documents and pending claim details are excluded from this view. Submissions remain in the separate claim portal.</p>`;}
function ensurePortalSession(){const old=db.sessionsByEmployee[employeeId]||null;db.session=portalSession(old,db.daily,employeeId,today());db.session.events ||= [];db.session.drafts ||= {};db.sessionsByEmployee[employeeId]=db.session;if(old!==db.session)persist();}
function previewAccount(id){const a=db.accounts.find(a=>a.employeeId===id);if(!a||a.status!=='Active'){toast('This demo account is suspended. Choose an active account.');return;}persist();employeeId=id;sessionStorage.setItem('bevy-preview-employee',id);role=a.role;profileId='';profileTab='Overview';dailyTab='My day';updateKind='mid';view='Dashboard';db.session=db.sessionsByEmployee[id]||null;render();}
function dayEvent(action,note=''){if(!db.session)return;db.session.events ||= [];db.session.events.push({at:Date.now(),action,note});}
function breakSeconds(s){return s?Math.floor((s.breakMs+(s.pausedAt?(s.ended||Date.now())-s.pausedAt:0))/1000):0;}
function workPanel(compact=false){const s=db.session,n=s?netSeconds(s):0;return `<section class="du-work-card ${compact?'compact':''}"><div class="du-work-top"><div><span class="live-indicator ${s?.pausedAt?'paused':''}"></span><span>${s?.ended?'WORKDAY CLOSED':s?.pausedAt?'ON A BREAK':'YOUR WORKING DAY'}</span></div><small>${date(s?.date||today())} · Asia/Dhaka</small></div><div class="du-work-body"><div><div class="du-clock" id="net-clock">${hms(n)}</div><div class="du-units">HOURS <span>MINUTES</span> SECONDS</div><p>${s?'Portal sign-in at '+time(new Date(s.started)):'Working time starts at portal sign-in.'}</p></div><div class="du-metrics"><div><span>Break time</span><b id="break-clock">${hms(breakSeconds(s))}</b><small>Automatically excluded</small></div><div><span>Total elapsed</span><b id="elapsed-clock">${hms(s?Math.floor(((s.ended||Date.now())-s.started)/1000):0)}</b><small>Work + breaks</small></div><div><span>Beyond 8 hours</span><b id="extra-clock">${hms(Math.max(0,n-28800))}</b><small>Recorded separately</small></div></div><div class="du-controls">${s&&!s.ended?`${btn(s.pausedAt?'▶ Resume work':'Ⅱ Take a break',s.pausedAt?'resume':'pause','du-pause')}${btn('Sign out of work ↗','sign-out','du-end')}`:'<div class="du-closed">✓ Workday closed</div>'}<small>${n>=28800?'8-hour target reached · extra time recorded':'Daily target: 8 net working hours'}</small></div></div><div class="du-progress"><i id="work-progress" style="width:${Math.min(100,n/288)}%"></i><span></span></div><div class="du-progress-labels"><span>Portal sign-in</span><span>4h · Mid-Day</span><span>8h · Daily target</span></div>${s&&s.date!==today()&&!s.ended?'<div class="du-stale">An earlier workday is still open. Finish it with a reason before a new day starts; recorded time is preserved.</div>':''}</section>`;}
function daily(){const s=db.session,e=person(employeeId),draft=s?.drafts?.[updateKind],value={progress:s?.[updateKind]||'',work_links:s?.[updateKind+'Evidence']||'',next_steps:s?.[updateKind+'Next']||'',blockers:s?.[updateKind+'Blocker']||'None',support_person:s?.[updateKind+'Support']||'',...draft},closed=!!s?.ended;return heading('Make today’s progress clear.','One daily thread. A shared view of what moves forward.',`<div class="du-date"><span id="live-date">${date(today())} · ${time(new Date())}</span><small>Asia/Dhaka · UTC +06:00</small></div>`)+`<div class="tabs du-tabs">${[['My day','My day'],['History','History'],...(can('daily')?[['Team','Team view'],['Reports','Reports']]:[])].map(([k,t])=>`<button data-daily-tab="${k}" class="${dailyTab===k?'active':''}">${t}</button>`).join('')}</div>`+(dailyTab==='History'?`<section class="card"><div class="section-head"><h2>My history</h2><span class="small muted">${esc(e.name)}</span></div>${dailyRecords(db.daily.filter(d=>d.employeeId===employeeId))}</section>`:(dailyTab==='Team'||dailyTab==='Reports')&&can('daily')?dailyTeam():workPanel()+`<div class="du-layout"><section class="card du-composer"><div class="section-head"><div><div class="eyebrow">SHARE YOUR PROGRESS</div><h2>Your daily update</h2></div><span class="small muted" id="draft-state">${draft?'Draft saved on this device':s?.[updateKind]?'Submitted · edit to save a revision':'Ready when you are'}</span></div><div class="du-checkpoints">${[['mid','01','Mid-Day update','Around 4 working hours'],['eod','02','End-of-day update','30–45 min before signing out']].map(([k,n,title,sub])=>`<button data-update-kind="${k}" class="${k===updateKind?'selected':''}"><span>${n}</span><div><b>${title}</b><small>${sub}</small></div>${badge(s?.[k]?'Submitted':k==='mid'&&s?.missReason?'Pending review':s?.ended?'Missing':k==='mid'&&s&&netSeconds(s)>=14400?'Due':'Upcoming')}</button>`).join('')}</div>${updateKind==='eod'?'<div class="du-handover"><b>↗ Leave a clear handover.</b> Submit before you finish, then stay available for 30–45 minutes for feedback. Working beyond 8 hours? Your timer keeps counting.</div>':'<p class="small muted">A quick snapshot of completed work, what’s next and where you need support.</p>'}<form id="daily-update-form"><fieldset ${closed?'disabled':''}><label><b>Completed tasks & progress <em>*</em></b><small>One task per line. Include the outcome or current status.</small><textarea name="progress" minlength="10" maxlength="6000" required class="du-task-area" placeholder="• Completed…&#10;• Progressed…&#10;• Reviewed…">${esc(value.progress)}</textarea></label><label>Work links & evidence <small>ClickUp, GitHub, Figma, Docs, campaigns, QA evidence or screenshot links. One link per line.</small><textarea name="work_links" maxlength="6000" placeholder="https://…">${esc(value.work_links)}</textarea></label><div class="form-grid"><label>Next priorities / remaining work *<textarea name="next_steps" minlength="5" maxlength="4000" required placeholder="What happens next?">${esc(value.next_steps)}</textarea></label><label>Blockers / help needed *<textarea name="blockers" minlength="3" maxlength="2000" required placeholder="No blockers, or describe the issue.">${esc(value.blockers)}</textarea></label></div><label>Support person / reporting manager <small>If blocked</small><input name="support_person" value="${esc(value.support_person)}" maxlength="300" placeholder="Who can help resolve this?"></label><div class="du-composer-actions">${updateKind==='mid'&&!s?.mid?btn('Can’t give a Mid-Day update?','miss-mid','text-btn'):'<span class="small muted">Your work, clearly documented.</span>'}<button class="primary" type="submit">${s?.[updateKind]?'Save revision':'Submit '+(updateKind==='mid'?'Mid-Day':'EOD')} ↗</button></div></fieldset></form>${s?.missReason&&updateKind==='mid'?`<div class="notice">Mid-Day note: ${esc(s.missReason)} · Pending HR review</div>`:''}${closed?'<div class="notice">This workday is closed. Corrections can be submitted from History and retain previous versions.</div>':''}</section><div class="du-aside"><section class="card"><div class="section-head"><div><div class="eyebrow">ONE DAILY THREAD</div><h2>Today’s activity</h2></div><span class="badge">${s?.events?.length||0}</span></div><div class="du-thread">${s?.events?.map(ev=>`<div class="du-event"><i></i><div><div><b>${esc(ev.action)}</b><time>${time(new Date(ev.at))}</time></div><p>${esc(ev.note)}</p>${ev.kind?btn('View update ↗','session-update-detail','text-btn',`data-kind="${ev.kind}"`):''}</div></div>`).join('')||'<p class="muted small">Your sign-in, breaks and updates appear here automatically.</p>'}${s&&!s.ended?`<div class="du-event current"><i></i><div><b>${s.pausedAt?'On a break':'Day in progress'}</b><p>${s.pausedAt?'Resume when you return.':'Your next action keeps the thread up to date.'}</p></div></div>`:''}</div></section><section class="card du-summary"><div class="eyebrow">YOUR DAY AT A GLANCE</div><h2>The full picture</h2><div><span>Working time</span><b id="summary-work">${hms(s?netSeconds(s):0)}</b></div><div><span>Break time</span><b id="summary-break">${hms(breakSeconds(s))}</b></div><div><span>Beyond 8 hours</span><b id="summary-extra">${hms(Math.max(0,(s?netSeconds(s):0)-28800))}</b></div><p>Breaks are excluded automatically. Work can continue beyond the 8-hour target.</p></section><p class="du-quiet">One thread for every role. Links and evidence follow your work—not your department.</p></div></div>`);}
function dailyRecords(a){return `<div class="table-wrap mobile-cards"><table><thead><tr>${['Date','Employee','Net / breaks','Mid-Day','EOD','Status',''].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${a.slice(0,100).map(d=>`<tr><td data-label="Date">${date(d.date)}</td><td data-label="Employee">${esc(person(d.employeeId)?.name||'Archived')}</td><td data-label="Time">${hms(d.net)}<small>Breaks ${hms(d.breaks)}</small>${d.net<28800?badge('Short hours'):''}</td><td data-label="Mid-Day">${d.mid?'Submitted':badge('Missing')} ${d.reason?'<small>Reason retained</small>':''}</td><td data-label="EOD">${d.eod?'Submitted':badge('Missing')}</td><td data-label="Status">${badge(d.status)}</td><td>${btn('Details','daily-detail','',`data-id="${d.id}"`)}${(can('daily')||d.employeeId===employeeId)?btn('Correct','correct-daily','',`data-id="${d.id}"`):''}${can('daily')?btn('Adjust time','edit-daily-time','',`data-id="${d.id}"`):''}${can('daily')&&d.status==='Pending review'?btn('Review','review-daily','',`data-id="${d.id}"`):''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No records yet.</td></tr>'}</tbody></table></div>`;}
function dailyTeam(){const a=db.daily.filter(d=>(reviewFilter==='All'||d.status===reviewFilter)&&(!filters.dailyFrom||d.date>=filters.dailyFrom)&&(!filters.dailyTo||d.date<=filters.dailyTo));const leaveToday=active().filter(e=>!reminderEligibility(e.id,today(),db.leaves).required);return `<div class="filters"><label>Record status<select id="review-filter">${options(['All','Submitted','Missing','Pending review','Excused'],reviewFilter)}</select></label><label>From<input type="date" id="daily-from" value="${filters.dailyFrom||''}"></label><label>To<input type="date" id="daily-to" value="${filters.dailyTo||''}"></label>${btn('This week','daily-week')}${btn('This month','daily-month')}${btn('All dates','daily-all')}${btn('Export CSV','export-daily','primary')}</div><div class="grid stats">${['Submitted','Missing','Pending review','Excused'].map(s=>stat(s,a.filter(d=>d.status===s).length,'Selected records','☷')).join('')}</div><div class="notice">Today: ${leaveToday.length} employees excluded from reminders because of approved leave or non-working day. Friday & Saturday are non-working days in this sample. Reminder delivery requires backend scheduling.</div>${btn('Review reminder eligibility','reminder-preview')} ${dailyRecords(a)}`;}
function scopeAudit(){return `<section class="card scope-audit"><div class="section-head"><div><div class="eyebrow">SOURCE DOCUMENT → DEMO</div><h2>Scope coverage, item by item</h2></div>${badge('12 scope sections reviewed')}</div><p class="small muted">Updated 12 November 2026 · Includes the current expense workflow and later owner decisions. Daily Updates is included in the prototype; Performance remains future. Roles: Super Admin / HR Admin / Employee.</p><div class="table-wrap mobile-cards"><table><thead><tr><th>Section</th><th>Requirement</th><th>Demo coverage</th><th>Status</th></tr></thead><tbody>${scopeRows.map(([n,title,body,status])=>`<tr><td data-label="Section">${n}</td><td data-label="Requirement"><b>${title}</b></td><td data-label="Demo coverage">${body}</td><td data-label="Status">${badge(status==='Future'?'Future':'Interactive demo')}</td></tr>`).join('')}</tbody></table></div><details class="field-checklist"><summary>Employee profile: every field in sections 3 and 4</summary>${profileGroups.map(([title,items])=>`<h3>${title}</h3><div class="field-chip-grid">${items.map(([,label])=>`<span>✓ ${label}</span>`).join('')}</div>`).join('')}<p>✓ Automatic Bevy experience &nbsp; ✓ Automatic total experience &nbsp; ✓ All 8 departments</p></details><div class="notice">Live insurance / Google Sheets sync, durable database permissions, email delivery and trusted server timestamps are backend integration work. Demo workflows are interactive and use fictional records.</div></section>`;}
function performance(){return heading('Performance, thoughtfully planned.','Available for future use after the final review framework is confirmed.')+`<section class="hero"><div><div class="eyebrow">FUTURE DEVELOPMENT</div><h2>A place for meaningful growth conversations.</h2><p class="small muted">The module stays available. No new scoring system, review cycle or framework is introduced in this scope.</p>${btn('Read implementation notes','guide','primary')}</div><div class="orb">◇</div></section><div class="grid two"><section class="card"><h2>Reserved for the approved framework</h2><ul class="checklist"><li>○ <div>Review cycle configuration<small>To be defined by HR and leadership.</small></div></li><li>○ <div>Review questions & scoring<small>Customize only after the framework is final.</small></div></li><li>○ <div>Access and reporting<small>Apply backend permissions before real use.</small></div></li></ul></section><section class="card"><h2>Current scope stays focused</h2><p class="muted small">People, assets, archives, branding, speed, leave, daily updates, insurance reporting and expense validation remain the implementation priorities.</p>${badge('Future · no current customization')}</section></div>`;}
const scopeRows=[['01','Simplify navigation','Recruitment, payroll, allowances, salary, shifts, work type, tags and employee asset requests are absent.','Current'],['02','Bevy branding','Portal, browser title, favicon and sample notification copy. Production email templates require backend changes.','Current'],['03–04','Profiles & confidentiality','All requested fields, auto experience, HR confidential view and editable fictional data.','Current'],['05','Search & filters','Name/email search with department, position, type, manager, location and employee status. Archived visibility requires archive access.','Current'],['06','Asset management','Create devices, exact assignment, profile linkage, optional return date and repair handling.','Current'],['07','Offboarding','Archive active employees, review after 30 days, keep/delete decisions and restore. No auto delete.','Current'],['08','Speed & usability','Small buildless frontend, responsive cards, local search, no third-party scripts or fonts. Production speed needs profiling.','Current'],['09','Insurance visibility','96 sample claims, confirmed-only employee view, stage averages, date/search filters, pagination, refresh failure scenario.','Current'],['10','Performance','Reserved module only. Await final performance framework.','Future'],['11','Daily updates','Included now: portal-entry timer, reference-style composer, break categories, daily thread, saved drafts, revisions, history and reports.','Current'],['12','Employee expenses & payroll handoff','Own-account submission, one expense date, required bill, HR / Super Admin validation only, duplicate checks, original currency + CAD, fixed-cycle/custom period preview, Late unpaid totals, saved one-time email matching, safe repeat sync, multi-employee runs, three-month fictional payroll replay and payroll-ready CSV. 28 fictional scenarios or zero-expense mode. Google writes are simulated.','Current']];
function guide(){return heading('A clear blueprint for the next build.','Review the experience, confirm the rules, then connect the existing portal backend.',`${btn('Print guide','print')}${superAdmin()?btn('Reset demo data','reset','danger'):''}`)+scopeAudit()+`<div class="guide-intro"><span class="guide-number">01—03</span><div><h2>One portal. Three clear roles.</h2><p>Super Admin owns access and configuration. HR Admin handles assigned HR operations. Employees use their own workspace.</p></div>${superAdmin()?btn('Explore access management →','open-access','primary'):btn('Open my workspace →','daily','primary')}</div><div class="role-grid">${ROLES.map((r,i)=>`<section class="card role-card"><span class="role-index">0${i+1}</span><h2>${r}</h2><p>${['Full administrative control, access assignments, settings and every HR module.','Daily HR operations with module access assigned by the Super Admin.','Own profile, assigned assets, leave, daily updates, expenses and sanitized insurance reporting.'][i]}</p><span class="badge">${i===0?'Controls access':i===1?'Delegated access':'Own records'}</span></section>`).join('')}</div><section class="card" style="margin-top:22px"><div class="section-head"><div><div class="eyebrow">REVIEW PATH</div><h2>A practical walkthrough</h2></div><span class="small muted">About 10 minutes</span></div><div class="walkthrough-grid">${[['01','Check the employee journey','Switch to Employee. Review the automatic work timer, own profile, leave and completed claims.'],['02','Follow the HR workflow','Search a profile, assign a device, review leave, offboard a sample record and inspect retention.'],['03','Review delegated access','As Super Admin, change a fictional HR Admin’s modules. Preview that user and verify the relevant menu and actions.'],['04','Test an expense payout','In Expenses, submit a bill as Employee; validate as HR / Super Admin. Prepare a payout, open Payroll sync, reconcile, then confirm a fictional payment. Use Controls & tests for 28 scenarios or zero expenses.'],['05','Close the workday','Post Mid-Day/EOD, take a category-based break, inspect the daily thread and sign out with the required summary.']].map(([n,title,text])=>`<div class="walkthrough-step"><span>${n}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}</div></section><section class="card" style="margin-top:22px"><div class="section-head"><h2>What is ready—and what connects next</h2><span class="badge">Implementation map</span></div><div class="table-wrap mobile-cards"><table><thead><tr><th>Area</th><th>Reviewable in this demo</th><th>Next development step</th></tr></thead><tbody>${[['Leave policy','Vacation 11; Floater Day 3; unlimited Sick Leave. Jan–Dec, no accrual/carry-over. Document threshold configurable (provisional: >2 working days).','See docs/LEAVE_AND_LOGIN.md: atomic balances, HR-only medical storage, yearly history and trusted login time'],['Identity & access','Three roles, delegated module/configuration/communication access, suspended samples and change history','Reuse portal identity; authorize every request on the server'],['Daily Updates','Portal-entry clock, breaks, drafts, posts, evidence, revisions, reports','Trusted server time, durable records, approved leave and reminders'],['People & assets','Editable profiles, exact devices, assignments, returns and archive decisions','Migrate fields, use database transactions and retain assignment history'],['Expenses','Dynamic category forms, required picture/PDF proof, HR / Super Admin validation only, period-based payroll runs, FX-locked payouts, summary CSV and expense-only ledger','Shared module v4.1; add server identity, private receipt storage, transactional validation and an expense-only Sheets connector. See docs/EXPENSE_PAYROLL_RUNBOOK.md'],['Insurance','Sanitized confirmed-payment reporting, filters and stage durations','Connect the existing tracker through a server-side field allowlist'],['Settings & announcements','Control centre, module configuration, editable announcements and notification templates','Persist approved settings and audience policies on the backend'],['Performance','Reserved module; no invented scoring framework','Customize after HR confirms the framework']].map(([a,b,c])=>`<tr><td data-label="Area"><b>${a}</b></td><td data-label="Demo">${b}</td><td data-label="Next">${c}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:22px"><div class="section-head"><h2>Permission model</h2></div>${permissionMatrix()}<div class="notice" style="margin-top:18px;margin-bottom:0">Access assignments here affect fictional records in this browser only. The role preview is for review; real HR authorization must be enforced by the existing portal backend. Company-domain protection for the hosted demo remains separate.</div></section><div class="grid two" style="margin-top:22px"><section class="card"><div class="section-head"><h2>Reviewer tools</h2><span class="badge">Sample workspace</span></div><p class="small muted">Scenarios let you test checkpoints without waiting. They replace only the current sample user’s active demo session.</p><div class="actions">${hr()?btn('Notification previews','notification-preview')+btn('Review reminder eligibility','reminder-preview')+btn('Load 4h scenario','scenario-mid')+btn('Load 8h scenario','scenario-eod'):'<span class="small muted">Switch to an administrative demo view to load scenarios.</span>'}${btn('Print build guide','print')}</div><p class="small muted" style="margin-top:20px">Source: <a href="https://github.com/shahriyarhassan-HR/bevy-hr-portal-prototype" target="_blank" rel="noopener noreferrer">Private GitHub repository ↗</a><br>See README, developer handoff, role policy, scope mapping and tests.</p></section><section class="card"><div class="section-head"><h2>Review notes</h2>${btn('+ Add a note','add-note','primary')}</div><p class="small muted">Capture decisions and export them for PM/dev review.</p>${db.notes.slice(0,4).map(n=>`<div class="note-card"><b>${esc(n.area)}</b> ${badge(n.priority)}<p>${esc(n.text)}</p></div>`).join('')||'<div class="empty">No notes yet. Add feedback while reviewing.</div>'}${btn('Export review notes','export-notes')}</section></div>`;}
function permissionMatrix(){return `<div class="table-wrap mobile-cards"><table><thead><tr><th>Capability</th><th>Super Admin</th><th>HR Admin</th><th>Employee</th></tr></thead><tbody>${[['Own workspace & daily updates','Yes','Yes','Own only'],['People, assets & HR operations','All modules','Assigned modules','Own profile/assets only'],['Expense validation & payroll export','All expense tools','Expenses module grant','Submit / track own only'],['Bank details & identifiers','Yes','If explicitly assigned','No'],['Team daily records & exports','Yes','If assigned','No'],['Grant roles, suspend accounts','Yes','No','No'],['Global identity & role settings','Yes','No','No'],['Module configuration','Yes','Configuration + module grant','No'],['Announcements & templates','Yes','Communications grant','Read announcements']].map(row=>`<tr>${row.map((c,i)=>`<td data-label="${['Capability','Super Admin','HR Admin','Employee'][i]}">${i===0?'<b>'+c+'</b>':c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function accessManagement(){if(!superAdmin())return denied();const a=db.accounts.filter(a=>{const e=person(a.employeeId);return e&&`${e.name} ${e.email}`.toLowerCase().includes(accessQuery.toLowerCase())&&(accessRole==='All roles'||a.role===accessRole);});const pages=Math.max(1,Math.ceil(a.length/10));accessPage=Math.min(accessPage,pages);return heading('The right access. Clearly assigned.','Super Admin manages roles and module permissions for the sample workforce.',btn('View permission model','permission-help'))+`<div class="access-banner"><span>⛨</span><div><b>You control administrative access.</b><p>Grant a role, adjust HR modules or suspend a sample account. Changes are recorded in the activity log.</p></div><span class="badge">Super Admin only</span></div><div class="grid stats access-stats">${ROLES.map(r=>stat(r,db.accounts.filter(a=>a.role===r&&a.status==='Active').length,'Active sample accounts','♧')).join('')}${stat('Suspended',db.accounts.filter(a=>a.status==='Suspended').length,'Access paused in the demo','Ⅱ')}</div><div class="filters"><input type="search" id="access-search" placeholder="Find an employee by name or email…" aria-label="Search access accounts" value="${esc(accessQuery)}"><label>Role<select id="access-role">${options(['All roles',...ROLES],accessRole)}</select></label>${btn('Clear filters','clear-access')}</div><div class="table-wrap mobile-cards"><table><thead><tr><th>Employee account</th><th>Role</th><th>Module access</th><th>Status</th><th>Actions</th></tr></thead><tbody>${a.slice((accessPage-1)*10,accessPage*10).map(a=>{const e=person(a.employeeId);return `<tr><td data-label="Employee"><div class="person"><span class="avatar">${initials(e.name)}</span><div><b>${esc(e.name)}</b><small>${esc(e.email)}${e.id===employeeId?' · You':''}</small></div></div></td><td data-label="Role">${badge(a.role)}</td><td data-label="Access">${a.role==='Super Admin'?'Full administrative control':a.role==='Employee'?'Personal workspace':a.grants.length+' of '+MODULES.length+' HR modules'}<small>${a.updatedAt?'Updated '+date(a.updatedAt.slice(0,10)):'Default access'}</small></td><td data-label="Status">${badge(a.status)}</td><td><div class="actions">${btn('Manage access','edit-access','',`data-id="${e.id}"`)}${btn('Preview','preview-account','',`data-id="${e.id}" ${a.status==='Suspended'?'disabled':''}`)}</div></td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">No matching employee accounts.</td></tr>'}</tbody></table></div><div class="pagination"><span>${a.length?((accessPage-1)*10+1):0}–${Math.min(accessPage*10,a.length)} of ${a.length} accounts</span><div class="actions">${btn('← Previous','access-prev','',accessPage===1?'disabled':'')}<span>${accessPage} / ${pages}</span>${btn('Next →','access-next','',accessPage===pages?'disabled':'')}</div></div><p class="small muted">Demo only: this does not invite people, send email, or change actual company/GitHub accounts. Whole-company demo sign-in protection remains unchanged.</p>`;}
function accessForm(id){if(!superAdmin())return;const a=db.accounts.find(a=>a.employeeId===id),e=person(id);if(!a||!e)return;modal('Manage employee access',`<div class="access-person"><span class="avatar">${initials(e.name)}</span><div><b>${esc(e.name)}</b><small>${esc(e.email)}</small></div></div><div class="form-grid">${select('role','Assigned role',ROLES,a.role)}${select('status','Portal access',['Active','Suspended'],a.status)}</div><div class="notice" id="role-help" style="margin-top:18px">${a.role==='Super Admin'?'Full access, including role assignments and portal settings.':a.role==='Employee'?'Own workspace only. Administrative modules are not available.':'Choose the HR operations this person can use.'}</div><div id="grant-options" class="grant-grid" ${a.role==='HR Admin'?'':'hidden'}>${MODULES.map(m=>`<label class="grant-option"><input type="checkbox" name="grants" value="${m.key}" ${a.grants.includes(m.key)?'checked':''}><span><b>${m.title}</b><small>${m.note}</small></span></label>`).join('')}</div>${textArea('reason','Reason for this access change','',true)}<p class="small muted">Changes apply to this fictional account only. You cannot suspend or remove your own Super Admin access.</p>`,f=>{const next={role:f.get('role'),status:f.get('status'),grants:f.getAll('grants'),updatedAt:new Date().toISOString(),reason:f.get('reason')};db.accounts=changeAccess(db.accounts,employeeId,id,next);audit('Employee access updated',e.name+' · '+a.role+' → '+next.role+' · '+next.status+' · '+next.reason);},'Save access');}
function portalSettings(){if(!superAdmin())return denied();return heading('A consistent Bevy workspace.','Manage the sample portal experience and keep company communications in one place.',btn('Module administration →','open-control','primary'))+`<div class="settings-layout"><section class="card"><div class="section-head"><div><div class="eyebrow">IDENTITY & WORKING RULES</div><h2>Portal configuration</h2></div>${badge('Bevy Commerce')}</div><div class="settings-brand"><img src="bevy-logo.svg" alt="Bevy Commerce"><div><b>Internal HR Portal</b><p>People & Culture</p></div></div>${fields({company:'Bevy Commerce',timezone:'Asia/Dhaka · UTC +06:00',target:'8 net working hours',start:'Automatically on portal sign-in',breaks:'Excluded during confirmed breaks',feedback:'30–45 minutes after EOD',roles:ROLES.join(' · ')},[['company','Company'],['timezone','Display timezone'],['target','Daily target'],['start','Workday starts'],['breaks','Break calculation'],['feedback','Feedback window'],['roles','Role model']])}<div class="notice" style="margin-top:22px;margin-bottom:0">Working rules match the approved prototype. Changes to policies should be agreed with HR before implementation.</div></section><section class="card"><div class="section-head"><div><div class="eyebrow">COMPANY COMMUNICATION</div><h2>Announcements</h2></div>${btn('+ New announcement','post-announcement','primary')}</div><p class="small muted">Pinned messages appear on the relevant dashboard. Sample messages stay in this browser.</p>${db.announcements.map(a=>`<div class="announcement"><div class="section-head"><span class="badge">${esc(a.audience)}</span>${btn('Edit','edit-announcement','text-btn',`data-id="${a.id}"`)}${btn('Remove','remove-announcement','text-btn',`data-id="${a.id}"`)}</div><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p><small>${date(a.at.slice(0,10))}</small></div>`).join('')||'<div class="empty">No announcements yet.</div>'}</section></div>`;}
function attentionItems(){const a=[];const s=db.session;if(db.settings.remindersEnabled&&dueReminders(s,employeeId,today(),db.leaves).items.some(i=>i.kind==='EOD'))a.push({title:'EOD update is due',note:'Share your handover before sign-out.',target:'Daily updates'});if(db.settings.remindersEnabled&&dueReminders(s,employeeId,today(),db.leaves).items.some(i=>i.kind==='Mid-Day'))a.push({title:'Mid-Day update is due',note:'Share progress or record a missed-update reason.',target:'Daily updates'});if(can('leave')){const n=db.leaves.filter(l=>l.status==='Pending').length;if(n)a.push({title:n+' leave requests need review',note:'Approve or decline requests with the correct context.',target:'Leave'});}if(can('daily')){const n=db.daily.filter(d=>d.status==='Pending review').length;if(n)a.push({title:n+' daily exceptions need review',note:'Review missed updates, short hours or corrections.',target:'Daily updates',team:true});}if(can('archives')){const n=db.employees.filter(e=>e.status==='Archived'&&archiveEligible(e.offboarded,today())).length;if(n)a.push({title:n+' archive decisions are available',note:'Keep records archived or follow the explicit deletion flow.',target:'Archived employees'});}return a;}
function showInbox(){const items=attentionItems();modal('Attention centre',`<p class="small muted">A focused view of outstanding work for your assigned role.</p>${items.map((a,i)=>`<div class="row"><span class="avatar">${i+1}</span><div class="grow"><strong>${esc(a.title)}</strong><p>${esc(a.note)}</p></div>${btn('Open →','open-attention','',`data-index="${i}"`)}</div>`).join('')||'<div class="empty">You are up to date. No outstanding actions for this view.</div>'}`);}
function quickSearch(){modal('Find a page or person',`<input id="quick-search-input" type="search" aria-label="Search workspace" placeholder="Try assets, insurance, or a colleague’s name…" autocomplete="off" style="width:100%"><div id="quick-search-results"></div>`);searchResults('');$('#quick-search-input').focus();}
function searchResults(query){const q=query.trim().toLowerCase(),pages=menu.filter(([v])=>mayView(v)&&v.toLowerCase().includes(q)),people=q&&can('people')?active().filter(e=>`${e.name} ${e.email}`.toLowerCase().includes(q)).slice(0,6):[];$('#quick-search-results').innerHTML=`<div class="nav-label" style="margin-left:0">PAGES</div>${pages.map(([v,i])=>`<button class="search-result" data-action="open-search-result" data-view="${v}"><span>${i}</span><b>${v}</b><span>→</span></button>`).join('')||'<p class="small muted">No matching pages.</p>'}${people.length?'<div class="nav-label" style="margin-left:0">PEOPLE</div>':''}${people.map(e=>`<button class="search-result" data-action="open-search-result" data-id="${e.id}"><span class="avatar">${initials(e.name)}</span><div><b>${esc(e.name)}</b><small>${esc(e.email)}</small></div><span>→</span></button>`).join('')}`;}
function activity(){if(!can('audit'))return denied();return heading('A visible trail of changes.','Demo audit events stay in this browser. Production needs a server-side audit log.')+`<section class="card">${db.audit.map(a=>`<div class="row"><span class="avatar">↗</span><div class="grow"><strong>${esc(a.action)}</strong><p>${esc(a.detail)}</p><small class="muted">${esc(a.actorName||'Demo workspace')} · ${esc(a.actorRole||'System')}</small></div><span class="small muted">${date(a.at.slice(0,10))}<br>${time(new Date(a.at))}</span></div>`).join('')}</section>`;}
function denied(){return '<div class="empty"><h1>Restricted view</h1><p>This area is reserved for the relevant role in this prototype.</p></div>';}
function navigate(v){if($('#modal').open)$('#modal').close();profileId='';view=v;document.body.classList.remove('menu-open');render();window.scrollTo({top:0});}
function modal(title,body,onSubmit,submit='Save changes'){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button type="button" data-action="close-modal" aria-label="Close dialog">×</button></div>${onSubmit?'<form id="dialog-form">':''}${body}<div class="error" id="form-error" role="alert"></div><div class="dialog-actions">${btn('Close','close-modal')}${onSubmit?`<button type="submit" class="primary">${submit}</button>`:''}</div>${onSubmit?'</form>':''}`;d.showModal();if(onSubmit)$('#dialog-form').onsubmit=e=>{e.preventDefault();try{const result=onSubmit(new FormData(e.currentTarget));if(result!==false){d.close();render();toast('Demo changes saved.');}}catch(err){$('#form-error').textContent=err.message;}};}
function input(name,label,value='',type='text',required=false){return `<label>${label}${required?' *':''}<input name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''} ${type==='text'?'maxlength="200"':''} ${type==='number'?'step="any" min="0"':''}></label>`;}
function select(name,label,arr,value,required=false){return `<label>${label}${required?' *':''}<select name="${name}" ${required?'required':''}>${options(arr,value)}</select></label>`;}
function textArea(name,label,value='',required=false){return `<label class="full">${label}<textarea name="${name}" maxlength="2000" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function editEmployee(id){if(!can('people'))return;const e=person(id),fresh=!e,base=e||{previousMonths:0,joined:today(),department:'Engineering',type:'Full-time',location:'Bangladesh',status:'Active',blood:'Not provided',gender:'Not provided'};
 const field=([k,l])=>k==='department'?select(k,l,departments,base[k],true):k==='type'?select(k,l,['Full-time','Contract'],base[k],true):k==='location'?select(k,l,['Bangladesh','Pakistan','Canada'],base[k],true):k==='blood'?select(k,l,bloodGroups,base[k]||'Not provided'):k==='gender'?select(k,l,['Not provided','Female','Male','Other','Prefer not to say'],base[k]||'Not provided'):input(k,l,base[k],k.toLowerCase().includes('email')?'email':['dob','joined'].includes(k)?'date':k==='previousMonths'?'number':['phone','emergency'].includes(k)?'tel':'text',['name','email','joined','position','manager','previousMonths'].includes(k));
 const groups=profileGroups.filter(([title])=>can('confidential')||!['Personal information','Confidential bank information'].includes(title));if(!can('confidential'))groups.unshift(['Basic identity',personalFields.filter(([k])=>['name','email'].includes(k))]);
 modal(fresh?'Add a fictional employee':'Edit employee profile',`<div class="notice">Scope §3–4 · Dummy information only. Required fields are marked *. Personal and bank information require Confidential details access.</div>${groups.map(([title,items],i)=>`<fieldset class="profile-form-section"><legend><span>0${i+1}</span> ${title}</legend><div class="form-grid">${items.map(field).join('')}</div>${title==='Education & experience'?'<p class="small muted">Enter previous experience in whole months: 1 year 6 months = 18. Bevy and total experience are calculated automatically.</p>':''}</fieldset>`).join('')}`,f=>{const data=validateProfile(Object.fromEntries([...f].map(([k,v])=>[k,typeof v==='string'?v.trim():v])),db.employees,id,today());if(!departments.includes(data.department)||!['Full-time','Contract'].includes(data.type)||!['Bangladesh','Pakistan','Canada'].includes(data.location))throw Error('Select a supported employment option.');if(fresh){data.id='EMP-'+Date.now();data.status='Active';db.employees.push(data);db.accounts.push({employeeId:data.id,role:'Employee',status:'Active',grants:[],reason:'New employee default'});}else Object.assign(e,data);audit(fresh?'Employee added':'Profile updated',data.name);},fresh?'Add employee':'Save profile');}
function assignDialog(id,emp){if(!can('assets'))return;const available=db.assets.filter(a=>['Available','Returned'].includes(a.status));if(!available.length){toast('No available devices. Add an asset or record a return.');return;}modal('Assign an exact device',`<div class="form-grid"><label class="full">Available device<select name="asset">${available.map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.name)} · ${a.serial}</option>`).join('')}</select></label><label class="full">Employee<select name="employee">${active().map(e=>`<option value="${e.id}" ${e.id===emp?'selected':''}>${esc(e.name)} · ${e.id}</option>`).join('')}</select></label>${input('assigned','Assignment date',today(),'date',true)}</div><p class="small muted">Return date can be added later, when the device is returned.</p>`,f=>{const index=db.assets.findIndex(a=>a.id===f.get('asset'));if(f.get('assigned')>today())throw Error('Assignment date cannot be in the future.');const before=db.assets[index];db.assets[index]={...assignAsset(before,person(f.get('employee')),f.get('assigned')),history:[...(before.history||[]),{action:'Assigned',date:f.get('assigned'),employeeId:f.get('employee'),at:new Date().toISOString()}]};audit('Device assigned',db.assets[index].serial+' → '+person(f.get('employee')).name);},'Assign device');}
function exportCSV(name,headers,rows){const safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';};download(name,'\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Export prepared.');}
function refreshClaims(){if(!claimFailure)lastRefresh=new Date();if(view==='Insurance')render();}
const actionPermission={'add-employee':'people','edit-profile':'people','export-employees':'people','add-asset':'assets','assign-asset':'assets','return-asset':'assets','repair-done':'assets','offboard':'archives','restore':'archives','keep-archived':'archives','delete-employee':'archives','approve-leave':'leave','decline-leave':'leave','hr-claims':'insurance','toggle-refresh':'insurance','daily-team':'daily','export-daily':'daily','review-daily':'daily','edit-asset':'assets','edit-leave':'leave','edit-archive':'archives','edit-daily-time':'daily','edit-claim':'insurance','reminder-preview':'daily'};
function handle(action,el){const id=el?.dataset.id;if(actionPermission[action]&&!can(actionPermission[action])){toast('This action is not included in your assigned access.');return;}if((['edit-access','save-settings'].includes(action)&&!superAdmin())||(['post-announcement','remove-announcement','edit-announcement','edit-template'].includes(action)&&!can('communications'))){toast('This setting requires the relevant administrative permission.');return;}const goto={guide:'Build guide',employees:'Employees',insurance:'Insurance',daily:'Daily updates',archives:'Archived employees',leave:'Leave'};if(goto[action]){navigate(goto[action]);return;}switch(action){case'reminder-preview':if(can('daily'))reminderPreview();break;case'notification-preview':if(hr())notificationPreview();break;case'open-performance':navigate('Performance');break;case'open-control':navigate('Control centre');break;case'edit-asset':editAssetForm(id);break;case'edit-leave':editLeaveForm(id);break;case'edit-archive':editArchiveForm(id);break;case'edit-daily-time':editDailyTimeForm(id);break;case'edit-claim':editClaimForm(id);break;case'module-policy':modulePolicy(el.dataset.module);break;case'edit-announcement':announcementForm(id);break;case'edit-template':templateForm(id);break;case'portal-login':loggedIn=true;sessionStorage.setItem('bevy-demo-login',today());render();break;case'login-preview':loggedIn=false;sessionStorage.removeItem('bevy-demo-login');render();break;case'open-access':navigate('Access management');break;case'permission-help':modal('How access works',permissionMatrix());break;case'edit-access':accessForm(id);break;case'preview-account':if(superAdmin()){$('#modal').close();previewAccount(id);}break;case'clear-access':accessQuery='';accessRole='All roles';accessPage=1;render();break;case'access-prev':accessPage--;render();break;case'access-next':accessPage++;render();break;case'quick-search':quickSearch();break;case'open-search-result':$('#modal').close();if(id&&can('people')){view='Employees';profileId=id;profileTab='Overview';render();}else if(el.dataset.view&&mayView(el.dataset.view))navigate(el.dataset.view);break;case'inbox':showInbox();break;case'open-attention':{const item=attentionItems()[+el.dataset.index];if(item){$('#modal').close();if(item.team)dailyTab='Team';navigate(item.target);}break;}case'post-announcement':modal('Post a sample announcement',`<div class="form-grid">${input('title','Title','','text',true)}${select('audience','Audience',['Everyone','Administrators'],'Everyone')}${textArea('body','Message','',true)}</div>`,f=>{db.announcements.unshift({id:'ANN-'+Date.now(),title:f.get('title'),body:f.get('body'),audience:f.get('audience'),at:new Date().toISOString()});audit('Sample announcement posted',f.get('title')+' · '+f.get('audience'));},'Post announcement');break;case'remove-announcement':db.announcements=db.announcements.filter(a=>a.id!==id);audit('Sample announcement removed',id);render();break;case'menu':document.body.classList.toggle('menu-open');break;case'close-modal':$('#modal').close();break;case'my-profile':view='My profile';profileId=employeeId;profileTab='Overview';render();break;case'back-employees':profileId='';navigate(lead()?'Employees':'Dashboard');break;case'profile':case'archived-profile':view='Employees';profileId=id;profileTab='Overview';render();break;case'emp-prev':empPage--;render();break;case'emp-next':empPage++;render();break;case'claim-prev':claimPage--;render();break;case'claim-next':claimPage++;render();break;case'clear-filters':empQuery='';filters={};empPage=1;render();break;case'clear-claims':claimPeriod='all';claimQuery='';claimPage=1;render();break;case'add-employee':editEmployee();break;case'edit-profile':editEmployee(id);break;case'assign-asset':assignDialog(id,el.dataset.employee);break;
case'asset-history':if(can('assets'))assetHistory(id);break;case'add-asset':if(!hr())return;modal('Add an inventory device',`<div class="form-grid">${select('type','Device type',['MacBook','iPhone','iPad','Other'],'MacBook')}${input('name','Device / model name','','text',true)}${input('model','Model number','','text',true)}${input('serial','Serial number','','text',true)}${select('status','Initial status',['Available','Repair'],'Available')}</div>`,f=>{const a=Object.fromEntries(f);if(db.assets.some(x=>x.serial.toLowerCase()===a.serial.trim().toLowerCase()))throw Error('Serial number is already recorded.');a.serial=a.serial.trim();a.id='AST-'+Date.now();db.assets.push(a);audit('Asset added',a.serial);});break;
case'return-asset':{if(!can('assets'))return;const a=db.assets.find(a=>a.id===id);modal('Record device return',`<p>${esc(a.name)} · ${esc(a.serial)}</p><div class="form-grid">${input('returned','Actual return date',today(),'date',true)}${select('condition','Return condition',['Returned','Repair'],'Returned')}</div>`,f=>{if(f.get('returned')<a.assigned||f.get('returned')>today())throw Error('Return date must be between assignment and today.');a.returned=f.get('returned');a.status=f.get('condition');a.history ||= [];a.history.push({action:'Returned · '+a.status,date:a.returned,employeeId:a.employeeId,at:new Date().toISOString()});audit('Device returned',a.serial+' · '+a.status);});break;}
case'repair-done':if(!hr())return;db.assets.find(a=>a.id===id).status='Available';audit('Device available after repair',id);render();break;
case'offboard':{if(!hr())return;const e=person(id),assigned=db.assets.filter(a=>a.employeeId===id&&a.status==='Assigned');modal('Offboard employee',`<p>Archive <b>${esc(e.name)}</b> and remove them from the active directory.</p><div class="notice ${assigned.length?'warn':''}">${assigned.length} device(s) remain assigned. Offboarding does not mark devices returned. Record actual returns in Assets.</div><div class="form-grid">${input('date','Offboarding date',today(),'date',true)}${textArea('reason','Offboarding note','Sample offboarding',true)}</div>`,f=>{if(e.id===employeeId)throw Error('Ask another authorized administrator to offboard your account.');if(f.get('date')>today()||f.get('date')<e.joined)throw Error('Offboarding date must be between joining date and today.');const accountToArchive=db.accounts.find(a=>a.employeeId===e.id);if(accountToArchive?.role==='Super Admin'&&accountToArchive.status==='Active')throw Error('Reassign Super Admin responsibility before offboarding this account.');if(accountToArchive)accountToArchive.status='Suspended';e.status='Archived';e.offboarded=f.get('date');e.archiveNote=f.get('reason');audit('Employee offboarded',e.name+' · '+assigned.length+' assigned device(s) to follow up');profileId='';view='Archived employees';},'Archive employee');break;}
case'restore':if(!hr())return;person(id).status='Active';const restoredAccount=db.accounts.find(a=>a.employeeId===id);if(restoredAccount)Object.assign(restoredAccount,{role:'Employee',status:'Active',grants:[]});else db.accounts.push({employeeId:id,role:'Employee',status:'Active',grants:[]});audit('Employee restored',person(id).name);render();break;
case'keep-archived':if(!hr())return;person(id).retentionDecisions ||= [];person(id).retentionDecisions.push({at:new Date().toISOString(),decision:'Keep archived',actorId:employeeId});audit('Archive retained',person(id).name);render();toast('Record kept archived.');break;
case'delete-employee':{if(!hr())return;const e=person(id);if(!archiveEligible(e.offboarded,today()))return;modal('Delete fictional employee record',`<div class="notice red">This removes the sample employee and related sample leave/daily records from this browser. Demo reset can restore the original dataset.</div><p>Type <b>${e.id}</b> to confirm deletion of ${esc(e.name)}.</p>${input('confirm','Employee ID','','text',true)}`,f=>{if(f.get('confirm')!==e.id)throw Error('Employee ID does not match.');if(db.assets.some(a=>a.employeeId===id&&a.status==='Assigned'))throw Error('Record device returns before deleting this employee.');db.employees=db.employees.filter(x=>x.id!==id);db.accounts=db.accounts.filter(a=>a.employeeId!==id);db.leaves=db.leaves.filter(x=>x.employeeId!==id);db.daily=db.daily.filter(x=>x.employeeId!==id);audit('Fictional employee deleted',e.id);},'Delete demo record');break;}
case'medical-policy':if(can('leave')&&can('configuration'))modal('Medical document policy',`<p>Confirm whether documentation is mandatory after 2 or after 3 working days. A one-day request always remains optional.</p>${select('threshold','Document required for more than',['2','3'],String(db.settings.medicalThreshold))}`,f=>{db.settings.medicalThreshold=Number(f.get('threshold'));audit('Medical threshold updated',db.settings.medicalThreshold+' working days');},'Save policy');break;
case'request-leave':modal('Request leave',`<div class="notice">Jan 1–Dec 31. No accrual or carry-over. Separate requests across year boundaries. Medical document required above ${db.settings.medicalThreshold} working days for Sick Leave; optional for one day.</div><div class="form-grid">${can('leave')?`<label class="full">Employee<select name="employee">${active().map(e=>`<option value="${e.id}" ${e.id===employeeId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>`:''}${select('type','Leave type',LEAVE_TYPES,'Vacation')}${input('from','From',today(),'date',true)}${input('to','To',today(),'date',true)}${textArea('reason','Reason','',true)}<label class="full">Medical document (Sick Leave)<input name="medical" type="file" accept=".pdf,.jpg,.jpeg,.png"><small>PDF/JPG/PNG, max 5 MB. Demo stores the filename only; production requires private secure uploads.</small></label></div>`,f=>{const file=f.get('medical');if(file?.size>5*1024*1024)throw Error('Maximum document size is 5 MB.');if(file?.size&&!/\.(pdf|jpe?g|png)$/i.test(file.name))throw Error('Use PDF, JPG or PNG.');const r={id:'LV-'+Date.now(),employeeId:can('leave')?f.get('employee'):employeeId,type:f.get('type'),from:f.get('from'),to:f.get('to'),reason:f.get('reason'),medicalDoc:f.get('type')==='Sick Leave'&&file?.size?file.name:'',status:'Pending'};r.days=validateLeave(r,db.leaves,db.settings.medicalThreshold);db.leaves.unshift(r);audit('Leave requested',r.type+' · '+r.days+' working days');},'Submit request');break;
case'approve-leave':case'decline-leave':if(!hr())return;if(action==='approve-leave'){const r=db.leaves.find(l=>l.id===id);try{validateLeave(r,db.leaves,db.settings.medicalThreshold,id);}catch(e){toast(e.message);return;}}db.leaves.find(l=>l.id===id).status=action==='approve-leave'?'Approved':'Declined';audit('Leave '+(action==='approve-leave'?'approved':'declined'),id);render();break;
case'claim-detail':{const c=db.claims.find(c=>c.id===id);if(!completed(c))return;modal('Claim payment timeline',`<p><b>${c.id}</b> · ${c.tracking} · ${esc(maskMemberId(c.member))} · ${c.type}</p><div class="timeline">${[[c.basis,c.start],['Insurer received',c.received],['Settlement',c.settled],['Bank receipt',c.bank]].map(([s,d])=>`<div class="stage"><small>${s}</small><b>${date(d)}</b></div>`).join('')}</div><div class="row"><div class="grow">Amount paid <b>${money(c.paid)}</b></div>${badge('Confirmed')}</div><p class="small muted">${workingDays(c.start,c.bank)} total working days · Stages ${stages(c).join(' / ')} · Basis: ${c.basis}. Friday/Saturday excluded.</p>`);break;}
case'refresh-claims':refreshClaims();toast(claimFailure?'Refresh failed. Cached sample data shown.':'Sample data refreshed.');break;
case'hr-claims':if(!hr())return;modal('HR-only tracker preview',`<div class="notice">Pending and unconfirmed details remain in the HR tracker. This sample is not connected to the live insurance sheet.</div><div class="actions">${btn(claimFailure?'Restore refresh success':'Simulate refresh failure','toggle-refresh')}</div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Claim</th><th>Status</th><th>Start</th><th></th></tr></thead><tbody>${db.claims.filter(c=>!completed(c)).map(c=>`<tr><td>${c.id}</td><td>${badge(c.status)}</td><td>${date(c.start)}</td><td>${btn('Edit sample','edit-claim','',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>`);break;
case'toggle-refresh':claimFailure=!claimFailure;$('#modal').close();refreshClaims();break;
case'daily-my':dailyTab='My day';render();break;case'daily-team':if(!lead())return;dailyTab='Team';render();break;
case'daily-week':filters.dailyFrom=shift(today(),-6);filters.dailyTo=today();render();break;case'daily-month':filters.dailyFrom=today().slice(0,7)+'-01';filters.dailyTo=today();render();break;case'daily-all':filters.dailyFrom='';filters.dailyTo='';render();break;
case'sign-in':db.session={started:Date.now(),date:today(),breakMs:0,pausedAt:0,mid:'',eod:'',missReason:'',revisions:[]};audit('Demo day signed in','Flexible start · 8h net target');render();break;
case'scenario-mid':case'scenario-eod':db.session={started:Date.now()-(action==='scenario-mid'?4:8)*3600000-1800000,date:today(),breakMs:1800000,pausedAt:0,mid:'',eod:'',missReason:'',revisions:[]};audit('Daily scenario loaded',action==='scenario-mid'?'4 net hours':'8 net hours');db.session.events=[{at:db.session.started,action:'Portal sign-in (test scenario)',note:'Demo workday loaded for review.'}];updateKind='mid';dailyTab='My day';view='Daily updates';persist();render();break;
case'pause':if(db.session&&!db.session.ended&&!db.session.pausedAt){modal('Start a break',`<p class="small muted">Working time pauses when you confirm. Resume when you return; break minutes are counted automatically.</p><div class="form-grid">${select('category','Break type',['General break','Lunch Break','Dinner Break','Prayer Break','Tea / Coffee Break','Personal Break','Other'],'General break')}${input('note','Note (optional)','','text')}</div>`,f=>{db.session.pausedAt=Date.now();const note=[f.get('category'),f.get('note')].filter(Boolean).join(' · ');dayEvent('Break started',note);audit('Break started',note);},'Start break Ⅱ');}break;
case'resume':if(db.session?.pausedAt&&!db.session.ended){db.session.breakMs+=Date.now()-db.session.pausedAt;db.session.pausedAt=0;dayEvent('Resumed work','Break time excluded automatically.');audit('Break ended','Net clock resumed');render();}break;
case'mid-update':case'eod-update':{const s=db.session;if(!s||s.ended)return;const mid=action==='mid-update',key=mid?'mid':'eod';modal(mid?'Mid-Day update':'End-of-day update',`<div class="form-grid">${textArea('progress','Progress / completed work',s[key]||'',true)}${input('evidence','Work / evidence link',s[key+'Evidence']||'','url')}${textArea('next','Next steps',s.next||'',!mid)}${input('blocker','Blockers',s.blocker||'None')}${input('support','Support person',s.support||'')}</div><p class="small muted">${mid?'Aim for around 4 net working hours.':'Submit before sign-out; normally allow 30–45 minutes for feedback.'} Any prior version is retained in demo history.</p>`,f=>{if(s[key])s.revisions.push({at:new Date().toISOString(),field:key,text:s[key]});s[key]=f.get('progress');s[key+'Evidence']=f.get('evidence');s[key+'At']=Date.now();s.next=f.get('next');s.blocker=f.get('blocker');s.support=f.get('support');dayEvent(mid?'Mid-Day update posted':'EOD update posted',s[key]);audit(mid?'Mid-Day submitted':'EOD submitted','Demo employee '+employeeId);},'Submit update');break;}
case'miss-mid':{const s=db.session;if(!s||s.ended)return;modal('Record missed Mid-Day reason',`<div class="form-grid">${select('category','Reason category',['Work pressure','Client emergency','Technical issue','Other'],'Workload')}${textArea('reason','Reason / context',s.missReason||'',true)}</div>`,f=>{s.missReason=f.get('category')+': '+f.get('reason');dayEvent('Mid-Day exception recorded',s.missReason);audit('Missed update reason recorded','Pending HR review');},'Save for review');break;}
case'sign-out':{const s=db.session;if(!s||s.ended)return;const n=netSeconds(s),warnings=[s.date!==today()?'Earlier workday still open':'',s.eodAt&&(Date.now()-s.eodAt)<1800000?'Feedback window under 30 minutes':'',!s.mid?'Missing Mid-Day':'',!s.eod?'Missing EOD':'',n<28800?'Short net hours':''].filter(Boolean);const feedback=s.eodAt?Math.floor((Date.now()-s.eodAt)/60000):0;modal('Review your sign-out',`<div class="timeline"><div class="stage"><small>Net work</small><strong style="font-size:22px">${hms(n)}</strong></div><div class="stage"><small>Total breaks</small><strong style="font-size:22px">${hms(Math.floor((s.breakMs+(s.pausedAt?Date.now()-s.pausedAt:0))/1000))}</strong></div><div class="stage"><small>Extra time</small><strong style="font-size:22px">${hms(Math.max(0,n-28800))}</strong></div></div><div class="notice ${warnings.length?'warn':''}" style="margin-top:18px">${warnings.length?warnings.join(' · '):'All required updates submitted.'} </div>${textArea('reason',warnings.length?'Exception reason (required)':'Optional sign-out note',s.missReason||'',warnings.length>0)}`,f=>{s.ended=Date.now();const record={id:'DAY-'+Date.now(),employeeId,date:s.date,net:netSeconds(s),breaks:Math.floor((s.breakMs+(s.pausedAt?s.ended-s.pausedAt:0))/1000),mid:s.mid,eod:s.eod,next:s.next||'',blocker:s.blocker||'',support:s.support||'',midEvidence:s.midEvidence||'',eodEvidence:s.eodEvidence||'',reason:f.get('reason'),status:warnings.length?'Pending review':'Submitted',revisions:s.revisions};dayEvent('Signed out of work',hms(record.net)+' net · '+hms(record.breaks)+' breaks'+(record.reason?' · '+record.reason:''));record.events=[...s.events];db.daily.unshift(record);audit('Workday signed out',hms(record.net)+' net · '+(warnings.join(', ')||'Complete'));},'Confirm sign-out');break;}
case'reset-session':toast('The next workday starts automatically at portal sign-in. Use Build guide for test scenarios.');break;
case'daily-detail':{const d=db.daily.find(x=>x.id===id);if(!d||(!can('daily')&&d.employeeId!==employeeId))return;modal('Daily record & revision history',`<p>${date(d.date)} · ${esc(person(d.employeeId)?.name)} · ${badge(d.status)}</p>${[['Mid-Day',d.mid],['EOD',d.eod],['Mid-Day evidence',d.midEvidence],['EOD evidence',d.eodEvidence],['Next steps',d.next],['Blockers',d.blocker],['Support',d.support],['Exception reason',d.reason]].map(([a,b])=>`<div class="field"><small>${a}</small><span>${esc(b||'Not submitted')}</span></div>`).join('')}<p class="small muted">${hms(d.net)} net · ${d.net<28800?'Short hours flag':'Target met'} · Missing updates and short hours are tracked separately.</p><h3>Revisions</h3>${d.revisions?.length?d.revisions.map(r=>`<div class="note-card"><small>${esc(r.at)} · ${esc(r.field||'Review')}</small><p>${esc(r.text)}</p></div>`).join(''):'<p class="small muted">No previous versions.</p>'}`);break;}
case'session-update-detail':{const s=db.session,k=el.dataset.kind;if(!s||!['mid','eod'].includes(k))return;const links=(s[k+'Evidence']||'').split('\n').filter(Boolean).map(l=>{try{const u=new URL(l.trim());if(!['http:','https:'].includes(u.protocol))return esc(l);return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(l)}</a>`;}catch{return esc(l);}}).join('<br>');modal(k==='mid'?'Mid-Day update':'End-of-day update',`<div class="field"><small>Completed tasks & progress</small><p style="white-space:pre-wrap">${esc(s[k])}</p></div><div class="field"><small>Work links & evidence</small>${links||'—'}</div>${fields({next:s[k+'Next'],blocker:s[k+'Blocker'],support:s[k+'Support']},[['next','Next priorities'],['blocker','Blockers'],['support','Support person']])}<h3 style="margin-top:22px">Revision history</h3>${s.revisions.filter(r=>r.field===k).map(r=>`<div class="note-card"><small>${esc(r.at)}</small><p>${esc(r.text)}</p></div>`).join('')||'<p class="small muted">No earlier versions.</p>'}`);break;}
case'correct-daily':{const d=db.daily.find(x=>x.id===id);if(!d||(!can('daily')&&d.employeeId!==employeeId))return;modal('Correct a daily record',`<div class="notice warn">Corrections preserve the previous version and return the record for HR review.</div><div class="form-grid">${textArea('mid','Mid-Day',d.mid)}${textArea('eod','EOD',d.eod)}${textArea('midEvidence','Mid-Day evidence links',d.midEvidence||'')}${textArea('eodEvidence','EOD evidence links',d.eodEvidence||'')}${textArea('next','Next steps',d.next||'')}${textArea('blocker','Blockers',d.blocker||'')}${input('support','Support person',d.support||'')}${textArea('reason','Correction reason','',true)}</div>`,f=>{d.revisions ||= [];d.revisions.push({at:new Date().toISOString(),field:'Correction',text:JSON.stringify({previous:{mid:d.mid,eod:d.eod,midEvidence:d.midEvidence,eodEvidence:d.eodEvidence,next:d.next,blocker:d.blocker,support:d.support,status:d.status},reason:f.get('reason')})});for(const key of ['mid','eod','midEvidence','eodEvidence','next','blocker','support'])d[key]=f.get(key);d.reason=f.get('reason');d.status='Pending review';audit('Daily record corrected',d.id+' · prior version retained');},'Save correction');break;}
case'review-daily':{if(!hr())return;const d=db.daily.find(d=>d.id===id);modal('Review daily exception',`<p>${esc(person(d.employeeId)?.name)} · ${date(d.date)}</p><div class="notice">${esc(d.reason||'No reason recorded')}</div><div class="form-grid">${select('status','Decision',['Excused','Missing'],'Excused')}${textArea('note','HR decision note','',true)}</div>`,f=>{d.revisions ||= [];d.revisions.push({at:new Date().toISOString(),field:'HR review',text:d.status+' → '+f.get('status')+': '+f.get('note')});d.status=f.get('status');audit('Daily exception reviewed',d.id+' · '+d.status);},'Save decision');break;}
case'export-employees':if(!lead())return;exportCSV('bevy-demo-employees.csv',['ID','Name','Company email','Department','Position','Type','Manager','Location','Joined'],filteredEmployees().map(e=>[e.id,e.name,e.email,e.department,e.position,e.type,e.manager,e.location,e.joined]));break;
case'export-daily':{if(!lead())return;const a=db.daily.filter(d=>(reviewFilter==='All'||d.status===reviewFilter)&&(!filters.dailyFrom||d.date>=filters.dailyFrom)&&(!filters.dailyTo||d.date<=filters.dailyTo));exportCSV('bevy-demo-daily-records.csv',['Date','Employee','Net','Breaks','Extra','Mid-Day','EOD','Short hours','Status','Reason','Revisions'],a.map(d=>[d.date,person(d.employeeId)?.name||d.employeeId,hms(d.net),hms(d.breaks),hms(Math.max(0,d.net-28800)),d.mid?'Submitted':'Missing',d.eod?'Submitted':'Missing',d.net<28800?'Yes':'No',d.status,d.reason,d.revisions?.length||0]));break;}
case'add-note':modal('Add a review note',`<div class="form-grid">${select('area','Area',menu.map(x=>x[0]),'Employees')}${select('priority','Priority',['Suggestion','Must fix','Question'],'Suggestion')}${textArea('text','Feedback','',true)}</div>`,f=>{db.notes.unshift({...Object.fromEntries(f),at:new Date().toISOString()});audit('Review note added',f.get('area'));});break;
case'export-notes':exportCSV('bevy-prototype-review-notes.csv',['Area','Priority','Feedback','Date'],db.notes.map(n=>[n.area,n.priority,n.text,n.at]));break;
case'print':window.print();break;
case'reset':if(!hr())return;modal('Reset fictional workspace',`<p>This restores the original sample data and removes changes and review notes in this browser. Export review notes first if needed.</p>${input('confirm','Type RESET','','text',true)}`,f=>{if(f.get('confirm')!=='RESET')throw Error('Type RESET to continue.');db=seed();initializeWorkspace();if(!db.accounts.some(a=>a.employeeId===employeeId))employeeId='EMP-001';persist();filters={};profileId='';empPage=1;claimPage=1;},'Reset demo');break;
}}
document.addEventListener('submit',e=>{if(e.target.id!=='daily-update-form')return;e.preventDefault();const session=db.session;if(!session||session.ended)return;const f=new FormData(e.target),k=updateKind,progress=String(f.get('progress')||'').trim(),links=String(f.get('work_links')||'').trim();if(progress.length<10)return;for(const line of links.split('\n').filter(Boolean)){try{const url=new URL(line.trim());if(!['http:','https:'].includes(url.protocol))throw Error();}catch{toast('Use a full http or https address for each evidence link.');return;}}if(session[k])session.revisions.push({at:new Date().toISOString(),field:k,text:JSON.stringify({progress:session[k],evidence:session[k+'Evidence'],next:session[k+'Next'],blocker:session[k+'Blocker'],support:session[k+'Support']})});session[k]=progress;session[k+'Evidence']=links;session[k+'Next']=f.get('next_steps');session[k+'Blocker']=f.get('blockers');session[k+'Support']=f.get('support_person');session.next=f.get('next_steps');session.blocker=f.get('blockers');session.support=f.get('support_person');session[k+'At']=Date.now();delete session.drafts[k];dayEvent(k==='mid'?'Mid-Day update posted':'EOD update posted',progress);session.events.at(-1).kind=k;audit('Daily update posted',k+' · revision history retained');render();toast('Your update has been posted.');});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const updated=JSON.parse(e.newValue);if(updated?.version===1){db=updated;if(!$('#modal').open&&!$('#daily-update-form')?.contains(document.activeElement))render();}}catch{}});
document.addEventListener('click',e=>{if(e.target.closest('[data-update-kind]')){updateKind=e.target.closest('[data-update-kind]').dataset.updateKind;render();return;}if(e.target.closest('[data-daily-tab]')){dailyTab=e.target.closest('[data-daily-tab]').dataset.dailyTab;if(!can('daily')&&['Team','Reports'].includes(dailyTab))dailyTab='My day';render();return;}const el=e.target.closest('button');if(!el)return;if(el.dataset.nav){navigate(el.dataset.nav);return;}if(el.dataset.profile){profileId=el.dataset.profile;profileTab='Overview';render();return;}if(el.dataset.profileTab){profileTab=el.dataset.profileTab;render();return;}if(el.dataset.action){e.preventDefault();handle(el.dataset.action,el);}});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='role'&&$('#grant-options')){const v=el.value;$('#grant-options').hidden=v!=='HR Admin';$('#role-help').textContent=v==='Super Admin'?'Full access, including role assignments and portal settings.':v==='Employee'?'Own workspace only. Administrative modules are not available.':'Choose the HR operations this person can use.';return;}if(el.id==='access-role'){accessRole=el.value;accessPage=1;render();return;}if(el.id==='role'){const chosen=db.accounts.find(a=>a.role===el.value&&a.status==='Active');if(chosen)previewAccount(chosen.employeeId);else {toast('No active account has this role. Assign one from Access management.');render();}return;}if(el.dataset.filter){filters[el.dataset.filter]=el.value;empPage=1;render();return;}switch(el.id){case'asset-status':filters.assetStatus=el.value;break;case'claim-period':claimPeriod=el.value;claimPage=1;break;case'claim-month':claimMonth=el.value;claimPage=1;break;case'claim-from':claimFrom=el.value;claimPage=1;break;case'claim-to':claimTo=el.value;claimPage=1;break;case'claim-size':claimSize=+el.value;claimPage=1;break;case'review-filter':reviewFilter=el.value;break;case'daily-from':filters.dailyFrom=el.value;break;case'daily-to':filters.dailyTo=el.value;break;default:return;}render();});
document.addEventListener('input',e=>{const el=e.target,id=el.id;if(id==='quick-search-input'){searchResults(el.value);return;}if(id==='access-search'){accessQuery=el.value;accessPage=1;const pos=el.selectionStart;render();$('#access-search').focus();$('#access-search').setSelectionRange(pos,pos);return;}const form=el.closest('#daily-update-form');if(form&&db.session&&!db.session.ended){db.session.drafts ||= {};db.session.drafts[updateKind]=Object.fromEntries(new FormData(form));persist();if($('#draft-state'))$('#draft-state').textContent='Draft saved on this device';return;}if(!['employee-search','asset-search','claim-search'].includes(id))return;const pos=el.selectionStart;if(id==='employee-search'){empQuery=el.value;empPage=1;}if(id==='asset-search')filters.assetQ=el.value;if(id==='claim-search'){claimQuery=el.value;claimPage=1;}render();const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos);});
setInterval(()=>{const s=db.session,n=s?netSeconds(s):0,br=breakSeconds(s);for(const [id,val] of [['portal-clock',hms(n)],['net-clock',hms(n)],['extra-clock',hms(Math.max(0,n-28800))],['break-clock',hms(br)],['elapsed-clock',hms(s?Math.floor(((s.ended||Date.now())-s.started)/1000):0)],['summary-work',hms(n)],['summary-break',hms(br)],['summary-extra',hms(Math.max(0,n-28800))]])if($('#'+id))$('#'+id).textContent=val;if($('#work-progress'))$('#work-progress').style.width=Math.min(100,n/288)+'%';if($('#live-date'))$('#live-date').textContent=date(today())+' · '+time(new Date());if(loggedIn&&s&&!s.ended&&db.settings.remindersEnabled){const due=dueReminders(s,employeeId,today(),db.leaves);for(const item of due.items){const key='reminded'+item.kind;if(!s[key]){s[key]=true;persist();const t=db.templates[item.kind==='Mid-Day'?'mid':'eod'];toast('Bevy Commerce · '+(t?.body||item.text).replaceAll('{{firstName}}',person(employeeId)?.name.split(' ')[0]||'colleague'));}}}},1000);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(loggedIn&&!$('#modal').open)quickSearch();}});
setInterval(()=>{if(!document.hidden)refreshClaims();},60000);
render();

function dashboardAnnouncement(){const a=db.announcements.find(a=>a.audience==='Everyone'||hr());return a?`<div class="dashboard-announcement"><span>✦</span><div><b>${esc(a.title)}</b><p>${esc(a.body)}</p></div><span class="badge">${esc(a.audience)}</span></div>`:'';}

// Administrative workflows are browser-local simulations of the documented API contracts.
function controlCentre(){if(!hr())return denied();const cards=[
 ['people','Employee records','Profiles, personal details, employment and automatic experience.','Employees','Edit employee from their profile. Confidential fields require separate permission.'],
 ['assets','Device inventory','Device details, assignments, returns, repairs and history.','Assets','Edit details separately from assignment/return lifecycle.'],
 ['leave','Leave administration','Edit requests, approve/decline and inspect policy rules.','Leave','Edits to approved requests return them to Pending for validation and review.'],
 ['insurance','Insurance reporting','Edit fictional tracker rows and preview dashboard projection.','Insurance','Production changes belong in the source tracker; no duplicate entry.'],
 ['daily','Daily Updates administration','Correct records, adjust recorded work/break time and review exceptions.','Daily updates','Corrections preserve prior values and return records to Pending review.'],
 ['archives','Archived employees','Correct offboarding details and record retention decisions.','Archived employees','30-day minimum and explicit delete confirmation remain enforced.']
 ];return heading('Administration, without guesswork.','A working preview of the tools behind each module.',superAdmin()?btn('Manage access','open-access','primary'):'')+`<div class="notice">Changes update fictional records in this browser and appear immediately in permitted portal views. Production API and database responsibilities are mapped in Build guide. Role assignments stay with Super Admin.</div><div class="admin-module-grid">${cards.map(([key,title,body,target,note])=>`<section class="card admin-module ${can(key)?'':'module-locked'}"><div class="section-head"><span class="eyebrow">${key.toUpperCase()}</span>${badge(can(key)?'Access granted':'Not assigned')}</div><h2>${title}</h2><p>${body}</p><small>${note}</small><div class="actions"><button data-nav="${target}" ${can(key)?'':'disabled'}>Open records →</button>${btn('Module settings','module-policy','',`data-module="${key}" ${can(key)&&can('configuration')?'':'disabled'}`)}</div></section>`).join('')}</div><section class="card" style="margin-top:22px"><div class="section-head"><div><div class="eyebrow">BEVY COMMUNICATIONS</div><h2>Announcements & notification templates</h2></div>${can('communications')?btn('+ Announcement','post-announcement','primary'):badge('Requires Communications access')}</div>${db.announcements.map(a=>`<div class="row"><div class="grow"><b>${esc(a.title)}</b><p>${esc(a.audience)} · ${esc(a.body)}</p></div>${can('communications')?btn('Edit','edit-announcement','',`data-id="${a.id}"`):''}</div>`).join('')}<div class="actions" style="margin-top:18px">${Object.entries(db.templates).map(([key,t])=>btn('Edit '+(key==='mid'?'Mid-Day':key==='eod'?'EOD':'leave')+' template','edit-template','',`data-id="${key}" ${can('communications')?'':'disabled'}`)).join('')}${btn('Preview messages','notification-preview')}</div></section><div class="grid two" style="margin-top:22px"><section class="card"><h2>Policies stay explicit.</h2><p class="small muted">Vacation 11 · Floater Day 3 · unlimited Sick Leave. Jan–Dec, no accrual or carry-over. Flexible 8-hour day. These approved rules are preserved; configurable medical thresholds and reminder preferences are shown separately.</p>${btn('Reminder eligibility','reminder-preview','',can('daily')?'':'disabled')}</section><section class="card"><h2>Performance · reserved</h2><p class="small muted">Module retained for the confirmed framework. No scoring, cycle or questionnaire has been invented. Configuration is intentionally deferred.</p>${btn('View future module','open-performance')}</section></div><p class="small muted">HR Admin receives module permissions and optional Configuration / Communications grants from Super Admin. Audit events retain actor and reason; they cannot be edited from this interface.</p>`;}
function modulePolicy(key){if(!can(key)||!can('configuration')){toast('Module access and Configuration permission are required.');return;}db.moduleSettings ||= {};const saved=db.moduleSettings[key]||{};
 const descriptions={people:'All profile fields in scope sections 3–4 are retained. Sensitive identifiers and bank data require Confidential details. Production APIs must use field-level authorization.',assets:'Assign only available/returned devices to active employees. Returns use actual dates. History is retained; assignment and return use separate operations.',leave:'Vacation 11, Floater Day 3 and unlimited Sick Leave. Jan–Dec. No accrual/carry-over. Pending requests reserve balances.',insurance:'The existing insurance tracker remains the source of truth. These settings are a connector blueprint; no live fetch or duplicate manual source is introduced.',daily:'Automatic workday on portal login. 8 net hours, Mid-Day at 4h, EOD 30–45 minutes before sign-out. Leave/weekend exclusions apply.',archives:'Minimum retention: 30 calendar days. No automatic deletion. Date correction requires a reason and an audit record.'};
 modal('Module settings · '+key,`<div class="notice">${descriptions[key]}</div><div class="form-grid">${key==='leave'?select('threshold','Sick document required above (working days)',['2','3'],String(db.settings.medicalThreshold)):''}${key==='daily'?select('reminders','In-app demo reminders',['Enabled','Disabled'],db.settings.remindersEnabled?'Enabled':'Disabled'):''}${key==='insurance'?`${input('source','Source tracker URL / reference',saved.source||'Existing HR insurance tracker')}${input('mapping','Source field mapping notes',saved.mapping||'Start: HR approval; bank receipt: confirmed date')}${select('pageSize','Default claims per page',['10','25'],String(db.settings.insurancePageSize))}`:''}${textArea('note','Implementation / policy note',saved.note||'')}${textArea('reason','Reason for this change','',true)}</div>`,f=>{db.moduleSettings[key]={...saved,note:f.get('note'),updatedAt:new Date().toISOString()};if(key==='leave')db.settings.medicalThreshold=Number(f.get('threshold'));if(key==='daily')db.settings.remindersEnabled=f.get('reminders')==='Enabled';if(key==='insurance'){db.moduleSettings[key].source=f.get('source');db.moduleSettings[key].mapping=f.get('mapping');db.settings.insurancePageSize=Number(f.get('pageSize'));claimSize=db.settings.insurancePageSize;}audit('Module configuration updated',key+' · '+f.get('reason'));},'Save configuration');}
function editAssetForm(id){if(!can('assets'))return;const a=db.assets.find(a=>a.id===id);if(!a)return;modal('Edit inventory device',`<div class="notice">Assignment state and return dates use their dedicated actions. Identity corrections preserve the previous values in history.</div><div class="form-grid">${select('type','Device type',['MacBook','iPhone','iPad','Other'],a.type)}${input('name','Device/model name',a.name,'text',true)}${input('model','Model number',a.model,'text',true)}${input('serial','Serial number',a.serial,'text',true)}${a.assigned?input('assigned','Correct assignment date',a.assigned,'date',true):''}${a.returned?input('returned','Correct return date',a.returned,'date',true):''}${textArea('reason','Correction reason','',true)}</div>`,f=>{const next=editAssetDetails(a,{type:f.get('type'),name:f.get('name').trim(),model:f.get('model').trim(),serial:f.get('serial'),...(f.has('assigned')?{assigned:f.get('assigned')}:{}),...(f.has('returned')?{returned:f.get('returned')}:{})},db.assets);next.history=[...(a.history||[]),{action:'Details corrected',date:today(),at:new Date().toISOString(),note:JSON.stringify({previous:{type:a.type,name:a.name,model:a.model,serial:a.serial,assigned:a.assigned,returned:a.returned},reason:f.get('reason')})}];db.assets[db.assets.indexOf(a)]=next;audit('Device details corrected',a.id+' · '+f.get('reason'));},'Save device');}
function assetHistory(id){const a=db.assets.find(a=>a.id===id);if(!a)return;modal('Device assignment & correction history',`<p><b>${esc(a.name)}</b> · ${esc(a.serial)}</p>${a.history?.length?a.history.map(h=>`<div class="note-card"><b>${esc(h.action)}</b><small>${date(h.date)} · ${esc(person(h.employeeId)?.name||'Administrator')}</small><p>${esc(h.note||'')}</p></div>`).join(''):'<div class="notice">Seeded inventory snapshot. New assignments, returns and corrections are recorded here.</div>'}`);}
function editLeaveForm(id){if(!can('leave'))return;const l=db.leaves.find(x=>x.id===id);if(!l)return;modal('Edit leave request',`<p>${esc(person(l.employeeId)?.name)} · ${badge(l.status)}</p><div class="notice">Any correction returns this request to Pending. Prior dates, type and decision are preserved for review.</div><div class="form-grid">${select('type','Leave type',LEAVE_TYPES,l.type)}${input('from','From',l.from,'date',true)}${input('to','To',l.to,'date',true)}${textArea('reason','Employee reason',l.reason,true)}${input('medicalDoc','Fictional medical document filename',l.medicalDoc||'')}${textArea('changeReason','Reason for correction','',true)}</div>`,f=>{const next={...l,type:f.get('type'),from:f.get('from'),to:f.get('to'),reason:f.get('reason'),medicalDoc:f.get('type')==='Sick Leave'?f.get('medicalDoc').trim():'',status:'Pending'};next.days=validateLeave(next,db.leaves,db.settings.medicalThreshold,id);next.revisions=[...(l.revisions||[]),{at:new Date().toISOString(),previous:{type:l.type,from:l.from,to:l.to,status:l.status,reason:l.reason},reason:f.get('changeReason')}];db.leaves[db.leaves.indexOf(l)]=next;audit('Leave request corrected',id+' · returned to Pending · '+f.get('changeReason'));},'Save for review');}
function editArchiveForm(id){if(!can('archives'))return;const e=person(id);if(!e||e.status!=='Archived')return;modal('Correct archive record',`<div class="notice">Retention is recalculated from the corrected offboarding date. No deletion occurs here.</div><div class="form-grid">${input('offboarded','Offboarding date',e.offboarded,'date',true)}${textArea('note','Archive note',e.archiveNote,true)}${textArea('reason','Correction reason','',true)}</div>`,f=>{const d=f.get('offboarded');if(d>today()||d<e.joined)throw Error('Offboarding date must be between joining and today.');e.archiveRevisions ||= [];e.archiveRevisions.push({date:e.offboarded,note:e.archiveNote,at:new Date().toISOString(),reason:f.get('reason')});e.offboarded=d;e.archiveNote=f.get('note');audit('Archive details corrected',id+' · '+f.get('reason'));},'Save archive');}
function editDailyTimeForm(id){if(!can('daily'))return;const d=db.daily.find(x=>x.id===id);if(!d)return;modal('Adjust recorded work & break time',`<p>${esc(person(d.employeeId)?.name)} · ${date(d.date)}</p><div class="notice">Administrative correction only. Original values are retained and this record returns to Pending review.</div><div class="form-grid">${input('net','Net working minutes',d.net/60,'number',true)}${input('breaks','Break minutes',d.breaks/60,'number',true)}${textArea('reason','Reason / supporting context','',true)}</div>`,f=>{db.daily[db.daily.indexOf(d)]=correctDailyTime(d,Number(f.get('net')),Number(f.get('breaks')),f.get('reason'));audit('Daily time corrected',id+' · '+f.get('reason'));},'Save correction');}
function editClaimForm(id){if(!can('insurance'))return;const c=db.claims.find(x=>x.id===id);if(!c)return;modal('Edit fictional source-tracker row',`<div class="notice">Demo fixture editor. Production changes must be made in the existing insurance tracker and synced to this reporting view. No live tracker is changed.</div><div class="form-grid">${input('tracking','Tracking reference',c.tracking,'text',true)}${input('member','Member ID (fictional)',c.member,'text',true)}${select('type','Claim type',['OPD','IPD','Maternity'],c.type)}${select('status','Tracker status',['Completed','Pending','Unconfirmed','Rejected','Overdue'],c.status)}${select('basis','Start basis',['HR approval','Actual submission'],c.basis)}${input('start','Start date',c.start,'date',true)}${input('received','Insurer received',c.received,'date')}${input('settled','Settlement date',c.settled,'date')}${input('bank','Bank receipt date',c.bank,'date')}${select('bankConfirmed','Bank receipt confirmed',['No','Yes'],c.bankConfirmed?'Yes':'No')}${input('paid','Amount paid (BDT)',c.paid,'number',true)}${textArea('reason','Correction reason','',true)}</div>`,f=>{const next=validateClaimFixture({...c,...Object.fromEntries(f),paid:Number(f.get('paid')),bankConfirmed:f.get('bankConfirmed')==='Yes'});delete next.reason;next.revisions=[...(c.revisions||[]),{at:new Date().toISOString(),previous:{...c,revisions:undefined},reason:f.get('reason')}];db.claims[db.claims.indexOf(c)]=next;lastRefresh=new Date();audit('Fictional source claim corrected',id+' · '+f.get('reason'));},'Save sample row');}
function announcementForm(id){if(!can('communications'))return;const a=db.announcements.find(a=>a.id===id);if(!a)return;modal('Edit announcement',`<div class="form-grid">${input('title','Title',a.title,'text',true)}${select('audience','Audience',['Everyone','Administrators'],a.audience)}${textArea('body','Message',a.body,true)}</div>`,f=>{Object.assign(a,Object.fromEntries(f),{updatedAt:new Date().toISOString()});audit('Announcement edited',a.title);},'Save announcement');}
function templateForm(id){if(!can('communications'))return;const t=db.templates[id];if(!t)return;modal('Edit Bevy notification template',`<div class="notice">Preview only. Supported tokens: {{firstName}}, {{leaveType}}, {{status}}. No email is sent.</div><div class="form-grid">${input('title','Subject',t.title,'text',true)}${textArea('body','Message',t.body,true)}</div>`,f=>{db.templates[id]={title:f.get('title'),body:f.get('body')};audit('Notification template edited',id);},'Save template');}
function notificationPreview(){if(!hr())return;const firstName=person(employeeId)?.name.split(' ')[0]||'colleague';modal('Bevy email & in-app previews',`<p class="small muted">Template previews only · Production delivery uses the existing portal notification service.</p>${Object.values(db.templates).map(t=>`<section class="notification-preview"><img src="bevy-logo.svg" width="85" alt="Bevy Commerce"><small>BEVY COMMERCE INTERNAL HR PORTAL</small><h3>${esc(t.title)}</h3><p>${esc(t.body.replaceAll('{{firstName}}',firstName).replaceAll('{{leaveType}}','Vacation').replaceAll('{{status}}','approved'))}</p><span>Open your Bevy workspace →</span><footer>People & Culture · Bevy Commerce</footer></section>`).join('')}`);}
function reminderPreview(){if(!can('daily'))return;const d=today();modal('Reminder eligibility · '+date(d),`<div class="notice">Live in-app demo checks use the same eligibility rule. Approved leave and Friday/Saturday suppress reminders. No email or Teams messages are sent.</div><div class="table-wrap mobile-cards"><table><thead><tr><th>Employee</th><th>Today</th><th>Due checkpoints</th></tr></thead><tbody>${active().map(e=>{const r=dueReminders(db.sessionsByEmployee[e.id],e.id,d,db.leaves);return `<tr><td data-label="Employee">${esc(e.name)}</td><td data-label="Eligibility">${badge(r.eligibility.required?'Required':'Excluded')}<small>${esc(r.eligibility.reason)}</small></td><td data-label="Checkpoints">${r.items.map(i=>i.kind).join(' · ')||(r.eligibility.required?'No open checkpoint due':'Suppressed')}</td></tr>`;}).join('')}</tbody></table></div>`);}

function expenseModule(){return heading('Expense workspace','Submit expenses. HR validates. Track reimbursement.')+`<div class="notice small">Signed in as <strong>${esc(person(employeeId)?.name)}</strong> · ${esc(account()?.role)}. Employees submit/view only their own claims. Every submission goes directly to HR / Super Admin for validation; no manager or colleague approval is needed.</div><iframe id="expense-module" title="Bevy employee expenses" src="expenses/index.html?embed=1" class="expense-frame"></iframe>`;}
function sendExpenseContext(){const frame=$('#expense-module');if(!frame||!loggedIn||account()?.status!=='Active')return;const allowed=active().filter(e=>db.accounts.some(a=>a.employeeId===e.id&&a.status==='Active'));const context={type:'bevy-expense-context',employee:person(employeeId).name,employeeId,role:account().role==='Super Admin'?'Super Admin':account().role==='HR Admin'&&can('expenses')?'HR':'Employee',employees:allowed.map(e=>({id:e.id,name:e.name,email:e.email,role:db.accounts.find(a=>a.employeeId===e.id)?.role,canReview:true}))};frame.contentWindow.postMessage(context,location.origin);}
window.addEventListener('message',e=>{const frame=$('#expense-module');if(e.origin===location.origin&&e.source===frame?.contentWindow&&e.data?.type==='bevy-expense-ready')sendExpenseContext();});

